VALUES ('doc-09-mitre-attack-p0-5470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T15:47:07.423Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [C0032](https://attack.mitre.org/campaigns/C0032) campaign, [TEMP.Veles](https://attack.mitre.org/groups/G0088) relied on encrypted SSH-based tunnels to transfer tools and for remote command/program execution.(Citation: FireEye TRITON 2019)", "external_references": [{"description": "Miller, S, et al. (2019, April 10). TRITON Actor TTP Profile, Custom Attack Tools, Detections, and ATT&CK Mapping. Retrieved April 16, 2019.", "source_name": "FireEye TRITON 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/04/triton-actor-ttp-profile-custom-attack-tools-detections.html"}], "id": "relationship--37de6975-01c6-497f-bf45-902c302fae66", "modified": "2026-07-31T18:47:25.921Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--7ec2826c-0bf0-4b47-acae-fd683431a4ca", "spec_version": "2.1", "target_ref": "attack-pattern--2db31dcd-54da-405d-acef-b9129b816ed6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5470', 0, 80, '09-mitre-attack', 'retrieved', 'C51C0E96E2F231A25EB3FFE6975B6CFCE7A8E9AAF7054969059ABA92372F3D79', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
