VALUES ('doc-09-mitre-attack-p0-5478', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T15:43:51.205Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [C0032](https://attack.mitre.org/campaigns/C0032) campaign, [TEMP.Veles](https://attack.mitre.org/groups/G0088) used VPN access to persist in the victim environment.(Citation: FireEye TRITON 2019)", "external_references": [{"description": "Miller, S, et al. (2019, April 10). TRITON Actor TTP Profile, Custom Attack Tools, Detections, and ATT&CK Mapping. Retrieved April 16, 2019.", "source_name": "FireEye TRITON 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/04/triton-actor-ttp-profile-custom-attack-tools-detections.html"}], "id": "relationship--c5a19163-a5b3-4b14-bf9d-d23d95d218d4", "modified": "2026-07-31T18:47:26.056Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--7ec2826c-0bf0-4b47-acae-fd683431a4ca", "spec_version": "2.1", "target_ref": "attack-pattern--10d51417-ee35-4589-b1ff-b6df1c334e8d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5478', 0, 76, '09-mitre-attack', 'retrieved', '3AC312227625C6C0D8F87976360A5149A4AD38D3FE9040DE57EECC637EA91927', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
