VALUES ('doc-09-mitre-attack-p0-5488', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T22:02:54.200Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: MSTIC NOBELIUM Mar 2021)", "external_references": [{"description": "Nafisi, R., Lelli, A. (2021, March 4). GoldMax, GoldFinder, and Sibot: Analyzing NOBELIUM’s layered persistence. Retrieved March 8, 2021.", "source_name": "MSTIC NOBELIUM Mar 2021", "url": "https://www.microsoft.com/security/blog/2021/03/04/goldmax-goldfinder-sibot-analyzing-nobelium-malware/"}], "id": "relationship--111d5f78-f5d3-4c33-b5f8-d978c166b52a", "modified": "2026-07-31T18:47:26.307Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "malware--5c747acd-47f0-4c5a-b9e5-213541fc01e0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5488', 0, 62, '09-mitre-attack', 'retrieved', '0AED521C8ADAE45CE5426BA643DB93326EF9F92719C8B3D7C7D113D3F4A32A8E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
