VALUES ('doc-09-mitre-attack-p0-5495', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T20:00:01.940Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) used forged SAML tokens that allowed the actors to impersonate users and bypass MFA, enabling [APT29](https://attack.mitre.org/groups/G0016) to access enterprise cloud applications and services.(Citation: Microsoft 365 Defender Solorigate)(Citation: Secureworks IRON RITUAL Profile)", "external_references": [{"description": "Microsoft 365 Defender Team. (2020, December 28). Using Microsoft 365 Defender to protect against Solorigate. Retrieved January 7, 2021.", "source_name": "Microsoft 365 Defender Solorigate", "url": "https://www.microsoft.com/security/blog/2020/12/28/using-microsoft-365-defender-to-coordinate-protection-against-solorigate/"}, {"description": "Secureworks CTU. (n.d.). IRON RITUAL. Retrieved February 24, 2022.", "source_name": "Secureworks IRON RITUAL Profile", "url": "https://www.sophos.com/en-us/threat-profiles/iron-ritual"}], "id": "relationship--2a8a7397-8977-4554-abbf-5168074cd4cc", "modified": "2026-07-31T18:47:26.423Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--51a14c76-dd3b-440b-9c20-2bf91d25a814", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5495', 0, 110, '09-mitre-attack', 'retrieved', 'BD8BD73318BD47BDCB2A70B7F16B862D18B53219E79ED2CA480FB7D413291EF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
