VALUES ('doc-09-mitre-attack-p0-5498', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T22:09:27.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Microsoft Deep Dive Solorigate January 2021)(Citation: CheckPoint Sunburst & Teardrop December 2020)(Citation: FireEye SUNBURST Backdoor December 2020)", "external_references": [{"description": "Check Point Research. (2020, December 22). SUNBURST, TEARDROP and the NetSec New Normal. Retrieved January 6, 2021.", "source_name": "CheckPoint Sunburst & Teardrop December 2020", "url": "https://research.checkpoint.com/2020/sunburst-teardrop-and-the-netsec-new-normal/"}, {"description": "FireEye. (2020, December 13). Highly Evasive Attacker Leverages SolarWinds Supply Chain to Compromise Multiple Global Victims With SUNBURST Backdoor. Retrieved January 4, 2021.", "source_name": "FireEye SUNBURST Backdoor December 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/12/evasive-attacker-leverages-solarwinds-supply-chain-compromises-with-sunburst-backdoor.html"}, {"description": "MSTIC, CDOC, 365 Defender Research Team. (2021, January 20). Deep dive into the Solorigate second-stage activation: From SUNBURST to TEARDROP and Raindrop . Retrieved January 22, 2021.", "source_name": "Microsoft Deep Dive Solorigate January 2021", "url": "https://www.microsoft.com/security/blog/2021/01/20/deep-dive-into-the-solorigate-second-stage-activation-from-sunburst-to-teardrop-and-raindrop/"}], "id": "relationship--378bf726-1fd4-4c08-939a-88fb11405205", "modified": "2026-07-31T18:47:26.464Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "malware--32f49626-87f4-4d6c-8f59-a0dca953fe26", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5498', 0, 144, '09-mitre-attack', 'retrieved', '396336BBE1CD816A347B77EAF07BE29F42ACAF9AF520EAFA92FDE1A6ED633691', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
