VALUES ('doc-09-mitre-attack-p0-5504', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T20:39:15.856Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) accessed victims'' internal knowledge repositories (wikis) to view sensitive corporate information on products, services, and internal business operations.(Citation: CrowdStrike StellarParticle January 2022)", "external_references": [{"description": "CrowdStrike. (2022, January 27). Early Bird Catches the Wormhole: Observations from the StellarParticle Campaign. Retrieved February 7, 2022.", "source_name": "CrowdStrike StellarParticle January 2022", "url": "https://www.crowdstrike.com/blog/observations-from-the-stellarparticle-campaign/"}], "id": "relationship--5377ce7e-ae13-4902-a7f9-98e83d04808b", "modified": "2026-07-31T18:47:26.593Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--d28ef391-8ed4-45dc-bc4a-2f43abf54416", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5504', 0, 83, '09-mitre-attack', 'retrieved', '542F3187995951651F17C3E58DC824CFFFFE1291F166B468B421031407151DA6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
