VALUES ('doc-09-mitre-attack-p0-5506', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T20:27:23.550Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) wrote malware such as [Sibot](https://attack.mitre.org/software/S0589) in Visual Basic.(Citation: Cybersecurity Advisory SVR TTP May 2021)", "external_references": [{"description": "NCSC, CISA, FBI, NSA. (2021, May 7). Further TTPs associated with SVR cyber actors. Retrieved July 29, 2021.", "source_name": "Cybersecurity Advisory SVR TTP May 2021", "url": "https://www.ncsc.gov.uk/files/Advisory-further-TTPs-associated-with-SVR-cyber-actors.pdf"}], "id": "relationship--59fd7bfd-f99b-4a76-9ea0-4fc89c27f204", "modified": "2026-07-31T18:47:26.622Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5506', 0, 77, '09-mitre-attack', 'retrieved', 'F3562C0B728F3FBF79F064FC64733A88E7B2B76B7799F517C5328511FE123731', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
