VALUES ('doc-09-mitre-attack-p0-5515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T16:12:59.131Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) obtained information about the configured Exchange virtual directory using `Get-WebServicesVirtualDirectory`.(Citation: Volexity SolarWinds)", "external_references": [{"description": "Cash, D. et al. (2020, December 14). Dark Halo Leverages SolarWinds Compromise to Breach Organizations. Retrieved December 29, 2020.", "source_name": "Volexity SolarWinds", "url": "https://www.volexity.com/blog/2020/12/14/dark-halo-leverages-solarwinds-compromise-to-breach-organizations/"}], "id": "relationship--755e4d65-4e9f-499c-93f3-2aa9a9404000", "modified": "2026-07-31T18:47:26.770Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5515', 0, 72, '09-mitre-attack', 'retrieved', '46471708C4BFBDC5093A2B71ECE86CD80D17D80E2195F4D11BC763013DB9B081', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
