VALUES ('doc-09-mitre-attack-p0-5517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T18:19:02.757Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) used [AdFind](https://attack.mitre.org/software/S0552) to enumerate remote systems.(Citation: Microsoft Deep Dive Solorigate January 2021)", "external_references": [{"description": "MSTIC, CDOC, 365 Defender Research Team. (2021, January 20). Deep dive into the Solorigate second-stage activation: From SUNBURST to TEARDROP and Raindrop . Retrieved January 22, 2021.", "source_name": "Microsoft Deep Dive Solorigate January 2021", "url": "https://www.microsoft.com/security/blog/2021/01/20/deep-dive-into-the-solorigate-second-stage-activation-from-sunburst-to-teardrop-and-raindrop/"}], "id": "relationship--7748c6c9-d7a5-44e9-81bf-97d038e6edb1", "modified": "2026-07-31T18:47:26.810Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5517', 0, 84, '09-mitre-attack', 'retrieved', 'AF596868977F9ABDA4D12497083AFBCC536F02147DF919BDEFFF1FC1F3B4099C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
