VALUES ('doc-09-mitre-attack-p0-5518', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T18:10:26.445Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) used WinRM via PowerShell to execute commands and payloads on remote hosts.(Citation: Symantec RAINDROP January 2021)", "external_references": [{"description": "Symantec Threat Hunter Team. (2021, January 18). Raindrop: New Malware Discovered in SolarWinds Investigation. Retrieved January 19, 2021.", "source_name": "Symantec RAINDROP January 2021", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/solarwinds-raindrop-malware"}], "id": "relationship--7779c4b8-d007-439a-81b7-b56efb8742ea", "modified": "2026-07-31T18:47:26.828Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--60d0c01d-e2bf-49dd-a453-f8a9c9fa6f65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5518', 0, 77, '09-mitre-attack', 'retrieved', '39CF1FD5E917BE7CBCBA76DC47625F6FC6B4AE950956923D57C41CE9A1438D5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
