VALUES ('doc-09-mitre-attack-p0-5527', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T21:16:26.853Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) downloaded source code from code repositories.(Citation: Microsoft Internal Solorigate Investigation Blog)", "external_references": [{"description": "MSRC Team. (2021, February 18). Microsoft Internal Solorigate Investigation – Final Update. Retrieved May 14, 2021.", "source_name": "Microsoft Internal Solorigate Investigation Blog", "url": "https://msrc-blog.microsoft.com/2021/02/18/microsoft-internal-solorigate-investigation-final-update/"}], "id": "relationship--93dc5023-3f2b-41a3-bd5a-68121a94280d", "modified": "2026-07-31T18:47:26.985Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--cff94884-3b1c-4987-a70b-6d5643c621c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5527', 0, 71, '09-mitre-attack', 'retrieved', '7BD57016B72A8FD2CF447828B38267849E79834D0655149CDDD111F199345490', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
