VALUES ('doc-09-mitre-attack-p0-5531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T20:46:54.907Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) stole Chrome browser cookies by copying the Chrome profile directories of targeted users.(Citation: CrowdStrike StellarParticle January 2022)", "external_references": [{"description": "CrowdStrike. (2022, January 27). Early Bird Catches the Wormhole: Observations from the StellarParticle Campaign. Retrieved February 7, 2022.", "source_name": "CrowdStrike StellarParticle January 2022", "url": "https://www.crowdstrike.com/blog/observations-from-the-stellarparticle-campaign/"}], "id": "relationship--95add276-6a4d-4281-82e5-7857b615742b", "modified": "2026-07-31T18:47:27.051Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--10ffac09-e42d-4f56-ab20-db94c67d76ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5531', 0, 78, '09-mitre-attack', 'retrieved', 'D8FDB70949769CDB8E011DC1950CED10CBCE59124FAB1F73A5420424DC3ED3C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
