VALUES ('doc-09-mitre-attack-p0-5534', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T15:22:32.052Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) staged data and files in password-protected archives on a victim''s OWA server.(Citation: Volexity SolarWinds)", "external_references": [{"description": "Cash, D. et al. (2020, December 14). Dark Halo Leverages SolarWinds Compromise to Breach Organizations. Retrieved December 29, 2020.", "source_name": "Volexity SolarWinds", "url": "https://www.volexity.com/blog/2020/12/14/dark-halo-leverages-solarwinds-compromise-to-breach-organizations/"}], "id": "relationship--9eb8df35-0cbf-490e-903a-f610a1387eb2", "modified": "2026-07-31T18:47:27.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--359b00ad-9425-420b-bba5-6de8d600cbc0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5534', 0, 74, '09-mitre-attack', 'retrieved', '1324C363E201D3BD29F9FDF759A0379AF3BC467A0579BDC02F7ECD72773FE8C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
