VALUES ('doc-09-mitre-attack-p0-5557', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T15:40:28.762Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [SolarWinds Compromise](https://attack.mitre.org/campaigns/C0024), [APT29](https://attack.mitre.org/groups/G0016) changed domain federation trust settings using Azure AD administrative permissions to configure the domain to accept authorization tokens signed by their own SAML signing certificate.(Citation: Secureworks IRON RITUAL Profile)(Citation: Microsoft 365 Defender Solorigate)", "external_references": [{"description": "Microsoft 365 Defender Team. (2020, December 28). Using Microsoft 365 Defender to protect against Solorigate. Retrieved January 7, 2021.", "source_name": "Microsoft 365 Defender Solorigate", "url": "https://www.microsoft.com/security/blog/2020/12/28/using-microsoft-365-defender-to-coordinate-protection-against-solorigate/"}, {"description": "Secureworks CTU. (n.d.). IRON RITUAL. Retrieved February 24, 2022.", "source_name": "Secureworks IRON RITUAL Profile", "url": "https://www.sophos.com/en-us/threat-profiles/iron-ritual"}], "id": "relationship--e43b9163-36cb-469a-9c47-9e4bd8af1383", "modified": "2026-07-31T18:47:27.600Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "attack-pattern--24769ab5-14bd-4f4e-a752-cfb185da53ee", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5557', 0, 112, '09-mitre-attack', 'retrieved', 'BB487FB63BBEDC62CB09EDC40472A8E8B2BC452C5C3C89A510632B466BAB9891', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
