VALUES ('doc-09-mitre-attack-p0-5565', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T22:13:48.078Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: NSA Joint Advisory SVR SolarWinds April 2021)(Citation: UK NSCS Russia SolarWinds April 2021)(Citation: Mandiant UNC2452 APT29 April 2022)", "external_references": [{"description": "Mandiant. (2022, April 27). Assembling the Russian Nesting Doll: UNC2452 Merged into APT29. Retrieved March 26, 2023.", "source_name": "Mandiant UNC2452 APT29 April 2022", "url": "https://www.mandiant.com/resources/blog/unc2452-merged-into-apt29"}, {"description": "NSA, FBI, DHS. (2021, April 15). Russian SVR Targets U.S. and Allied Networks. Retrieved April 16, 2021.", "source_name": "NSA Joint Advisory SVR SolarWinds April 2021", "url": "https://media.defense.gov/2021/Apr/15/2002621240/-1/-1/0/CSA_SVR_TARGETS_US_ALLIES_UOO13234021.PDF/CSA_SVR_TARGETS_US_ALLIES_UOO13234021.PDF"}, {"description": "UK NCSC. (2021, April 15). UK and US call out Russia for SolarWinds compromise. Retrieved April 16, 2021.", "source_name": "UK NSCS Russia SolarWinds April 2021", "url": "https://www.ncsc.gov.uk/news/uk-and-us-call-out-russia-for-solarwinds-compromise"}], "id": "relationship--3b2680f0-aa69-4766-ab41-9123373ffa4e", "modified": "2026-07-31T18:48:07.725Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "attributed-to", "revoked": false, "source_ref": "campaign--808d6b30-df4e-4341-8248-724da4bac650", "spec_version": "2.1", "target_ref": "intrusion-set--899ce53f-13a0-479b-a0e4-67d46e241542", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5565', 0, 131, '09-mitre-attack', 'retrieved', '22F18D15A65BA510466D93A98045714962FA0029B117549E357351A7A92C49FC', 'v1', '{"source_id": "09-mi