VALUES ('doc-09-mitre-attack-p0-5589', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-19T15:13:16.810Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ANELLDR](https://attack.mitre.org/software/S9027) was used in [Operation AkaiRyū](https://attack.mitre.org/campaigns/C0060) as part of [UPPERCUT](https://attack.mitre.org/software/S0275) infection chains.(Citation: Trend Micro Earth Kasha Anel NOV 2024)(Citation: ESET MirrorFace 2025)", "external_references": [{"description": " Dominik Breitenbacher. (2025, March 18). Operation AkaiRyū: MirrorFace invites Europe to Expo 2025 and revives ANEL backdoor. Retrieved May 22, 2025.", "source_name": "ESET MirrorFace 2025", "url": "https://www.welivesecurity.com/en/eset-research/operation-akairyu-mirrorface-invites-europe-expo-2025-revives-anel-backdoor/"}, {"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}], "id": "relationship--5a86d1f6-5f6a-4bd9-bc0c-d8c46d3233b8", "modified": "2026-07-31T18:47:26.984Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--8a7c55ea-f363-4a03-b4c5-fa3fdb132d8f", "spec_version": "2.1", "target_ref": "malware--c21edbd1-a0a4-4c3c-9b22-4a49634186c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5589', 0, 118, '09-mitre-attack', 'retrieved', 'BFD78C6074BAE76A2ACDDC61806B10FEDFA42FCC0A6F592DE8E76998F06E74EC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version