VALUES ('doc-09-mitre-attack-p0-5605', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-19T16:22:56.327Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation AkaiRyū](https://attack.mitre.org/campaigns/C0060), [MirrorFace](https://attack.mitre.org/groups/G1054) loaded malicious Word templates containing VBA code leading to installation of [UPPERCUT](https://attack.mitre.org/software/S0275).(Citation: ESET MirrorFace 2025)", "external_references": [{"description": " Dominik Breitenbacher. (2025, March 18). Operation AkaiRyū: MirrorFace invites Europe to Expo 2025 and revives ANEL backdoor. Retrieved May 22, 2025.", "source_name": "ESET MirrorFace 2025", "url": "https://www.welivesecurity.com/en/eset-research/operation-akairyu-mirrorface-invites-europe-expo-2025-revives-anel-backdoor/"}], "id": "relationship--c3d716d9-a94d-49a7-af66-0166d9fe1f58", "modified": "2026-07-31T18:47:27.317Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--8a7c55ea-f363-4a03-b4c5-fa3fdb132d8f", "spec_version": "2.1", "target_ref": "attack-pattern--79a47ad0-fc3b-4821-9f01-a026b1ddba21", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5605', 0, 78, '09-mitre-attack', 'retrieved', '384955D12E70909A43680BBAA974D3725293AC50C7BFBB308523704042C2996F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
