VALUES ('doc-09-mitre-attack-p0-5606', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T20:25:41.881Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation AkaiRyū](https://attack.mitre.org/campaigns/C0060), [MirrorFace](https://attack.mitre.org/groups/G1054) disguised LNK and SFX (self-extracting) files as Word documents to lure victims into opening malicious files.(Citation: Trend Micro Earth Kasha Anel NOV 2024)(Citation: ESET MirrorFace 2025)", "external_references": [{"description": " Dominik Breitenbacher. (2025, March 18). Operation AkaiRyū: MirrorFace invites Europe to Expo 2025 and revives ANEL backdoor. Retrieved May 22, 2025.", "source_name": "ESET MirrorFace 2025", "url": "https://www.welivesecurity.com/en/eset-research/operation-akairyu-mirrorface-invites-europe-expo-2025-revives-anel-backdoor/"}, {"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}], "id": "relationship--c5f5995d-2792-4571-95c4-3085b843d917", "modified": "2026-07-31T18:47:27.340Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--8a7c55ea-f363-4a03-b4c5-fa3fdb132d8f", "spec_version": "2.1", "target_ref": "attack-pattern--208884f1-7b83-4473-ac22-4e1cf6c41471", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5606', 0, 126, '09-mitre-attack', 'retrieved', '77E2914499992D86EB7CF2631E85DA3A908ADB4B9391C46110C171FF036DBF0C', 'v1', '{"source_id": "09-mitre-attack", "versi