VALUES ('doc-09-mitre-attack-p0-5649', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-06T21:30:32.623Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation CuckooBees](https://attack.mitre.org/campaigns/C0012), the threat actors used the `query user` and `whoami` commands as part of their advanced reconnaissance.(Citation: Cybereason OperationCuckooBees May 2022)", "external_references": [{"description": "Cybereason Nocturnus. (2022, May 4). Operation CuckooBees: Deep-Dive into Stealthy Winnti Techniques. Retrieved September 22, 2022.", "source_name": "Cybereason OperationCuckooBees May 2022", "url": "https://www.cybereason.com/blog/operation-cuckoobees-deep-dive-into-stealthy-winnti-techniques"}], "id": "relationship--71f80d4d-daf5-4da2-811b-0ebd3365b79c", "modified": "2026-07-31T18:47:28.334Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--93c23946-49af-41f4-ac03-40f9ffc7419b", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5649', 0, 77, '09-mitre-attack', 'retrieved', '54E84F565FC34D392D721BF840B8CB7030E0FCCF11CF1367B218E8E27F3102D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
