VALUES ('doc-09-mitre-attack-p0-5651', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-27T22:38:06.799Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation CuckooBees](https://attack.mitre.org/campaigns/C0012), the threat actors used the `dsquery` and `dsget` commands to get domain environment information and to query users in administrative groups.(Citation: Cybereason OperationCuckooBees May 2022)", "external_references": [{"description": "Cybereason Nocturnus. (2022, May 4). Operation CuckooBees: Deep-Dive into Stealthy Winnti Techniques. Retrieved September 22, 2022.", "source_name": "Cybereason OperationCuckooBees May 2022", "url": "https://www.cybereason.com/blog/operation-cuckoobees-deep-dive-into-stealthy-winnti-techniques"}], "id": "relationship--7903f25e-388e-4cda-bd09-bc83fa64d62e", "modified": "2026-07-31T18:47:28.368Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--93c23946-49af-41f4-ac03-40f9ffc7419b", "spec_version": "2.1", "target_ref": "attack-pattern--21875073-b0ee-49e3-9077-1e2a885359af", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5651', 0, 82, '09-mitre-attack', 'retrieved', '11AB16C6F61FE96E6779795DBA1769A1088E3710A8FDF1B03791D461E46B0E0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
