VALUES ('doc-09-mitre-attack-p0-5658', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-22T20:20:46.991Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation CuckooBees](https://attack.mitre.org/campaigns/C0012), the threat actors generated a web shell within a vulnerable Enterprise Resource Planning Web Application Server as a persistence mechanism.(Citation: Cybereason OperationCuckooBees May 2022)", "external_references": [{"description": "Cybereason Nocturnus. (2022, May 4). Operation CuckooBees: Deep-Dive into Stealthy Winnti Techniques. Retrieved September 22, 2022.", "source_name": "Cybereason OperationCuckooBees May 2022", "url": "https://www.cybereason.com/blog/operation-cuckoobees-deep-dive-into-stealthy-winnti-techniques"}], "id": "relationship--b3fc9f8c-9074-42b8-a144-ad97aa017dce", "modified": "2026-07-31T18:47:28.527Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--93c23946-49af-41f4-ac03-40f9ffc7419b", "spec_version": "2.1", "target_ref": "attack-pattern--5d0d3609-d06d-49e1-b9c9-b544e0c618cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5658', 0, 81, '09-mitre-attack', 'retrieved', '9CAD6A7B0904DB2A56AC1C7D9A42CA32716956E6B02F68D6354FC097AD33407F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
