VALUES ('doc-09-mitre-attack-p0-5668', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-06T21:04:43.373Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation CuckooBees](https://attack.mitre.org/campaigns/C0012), the threat actors collected data, files, and other information from compromised networks.(Citation: Cybereason OperationCuckooBees May 2022)", "external_references": [{"description": "Cybereason Nocturnus. (2022, May 4). Operation CuckooBees: Deep-Dive into Stealthy Winnti Techniques. Retrieved September 22, 2022.", "source_name": "Cybereason OperationCuckooBees May 2022", "url": "https://www.cybereason.com/blog/operation-cuckoobees-deep-dive-into-stealthy-winnti-techniques"}], "id": "relationship--ea944454-a4e9-44fb-9cf1-3f018a455740", "modified": "2026-07-31T18:47:28.729Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--93c23946-49af-41f4-ac03-40f9ffc7419b", "spec_version": "2.1", "target_ref": "attack-pattern--3c4a2599-71ee-4405-ba1e-0e28414b4bc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5668', 0, 73, '09-mitre-attack', 'retrieved', 'B1825B1E16E4A47AD7E8859E32DDBB6D2196DD1830023D644F59EAF657A74D45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
