VALUES ('doc-09-mitre-attack-p0-5676', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T15:17:14.443Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059), threat actors used voice calls to socially engineer victims into authorizing a modified version of the Salesforce Data Loader app.(Citation: Google Salesforce JUN 2025)", "external_references": [{"description": "Google Threat Intelligence Group. (2025, June 4). The Cost of a Call: From Voice Phishing to Data Extortion. Retrieved October 22, 2025.", "source_name": "Google Salesforce JUN 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/voice-phishing-data-extortion"}], "id": "relationship--4d7fd920-ea04-483b-98bf-dbf7bfac67f4", "modified": "2026-07-31T20:48:18.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--9cea8bec-07c5-422b-84b8-99d3128ce570", "spec_version": "2.1", "target_ref": "attack-pattern--42e8de7b-37b2-4258-905a-6897815e58e0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5676', 0, 88, '09-mitre-attack', 'retrieved', '968D1162A51B71B254879467B4FD7BFFEF71808A5AD8272920DD9E6824C914AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
