VALUES ('doc-09-mitre-attack-p0-5680', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T15:35:03.375Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059), threat actors used [Tor](https://attack.mitre.org/software/S0183) IPs for voice calls and for the collection of stolen data.(Citation: Google Salesforce JUN 2025)", "external_references": [{"description": "Google Threat Intelligence Group. (2025, June 4). The Cost of a Call: From Voice Phishing to Data Extortion. Retrieved October 22, 2025.", "source_name": "Google Salesforce JUN 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/voice-phishing-data-extortion"}], "id": "relationship--74ca2dd6-3194-42f3-bee6-6a9a59b082ab", "modified": "2026-07-31T20:48:18.276Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--9cea8bec-07c5-422b-84b8-99d3128ce570", "spec_version": "2.1", "target_ref": "attack-pattern--a782ebe2-daba-42c7-bc82-e8e9d923162d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5680', 0, 83, '09-mitre-attack', 'retrieved', '64AAAF8BBF41E0F2D4CEA5A61CEE57D8D6261AF5FD566CD01DE655999C7DE664', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
