VALUES ('doc-09-mitre-attack-p0-5684', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T17:20:38.797Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059), threat actors used API queries to automatically exfiltrate large volumes of data.(Citation: FBI Salesforce Data Theft SEP 2025)", "external_references": [{"description": "FBI Cyber Division. (2025, September 12). Cyber Criminal Groups UNC6040 and UNC6395 Compromising Salesforce Instances for Data Theft and Extortion. Retrieved October 22, 2025.", "source_name": "FBI Salesforce Data Theft SEP 2025", "url": "https://www.ic3.gov/CSA/2025/250912.pdf"}], "id": "relationship--ad3b3ea9-04f8-42f7-b88a-0d33fdb3854e", "modified": "2026-07-31T20:48:18.305Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--9cea8bec-07c5-422b-84b8-99d3128ce570", "spec_version": "2.1", "target_ref": "attack-pattern--774a3188-6ba9-4dc4-879d-d54ee48a5ce9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5684', 0, 86, '09-mitre-attack', 'retrieved', '6929B7DAB8CA7C7EF920277198E95556667E8F58AECB01C188BCA511008513D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
