VALUES ('doc-09-mitre-attack-p0-5686', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T15:25:16.271Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059), threat actors initiated voice calls with victims to socially engineer them into authorizing malicious applications or divulging sensitive credentials.(Citation: FBI Salesforce Data Theft SEP 2025)(Citation: Google Salesforce JUN 2025)", "external_references": [{"description": "FBI Cyber Division. (2025, September 12). Cyber Criminal Groups UNC6040 and UNC6395 Compromising Salesforce Instances for Data Theft and Extortion. Retrieved October 22, 2025.", "source_name": "FBI Salesforce Data Theft SEP 2025", "url": "https://www.ic3.gov/CSA/2025/250912.pdf"}, {"description": "Google Threat Intelligence Group. (2025, June 4). The Cost of a Call: From Voice Phishing to Data Extortion. Retrieved October 22, 2025.", "source_name": "Google Salesforce JUN 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/voice-phishing-data-extortion"}], "id": "relationship--db256e63-e369-4fc4-985a-ce830f4292b9", "modified": "2026-07-31T20:48:18.320Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--9cea8bec-07c5-422b-84b8-99d3128ce570", "spec_version": "2.1", "target_ref": "attack-pattern--6a5d222a-a7e0-4656-b110-782c33098289", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5686', 0, 127, '09-mitre-attack', 'retrieved', '8AEC8444E84364B4CEEB4508712A2F891ACCA36358A85ABC3A34F842D9C7A8D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
