VALUES ('doc-09-mitre-attack-p0-5687', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T15:32:44.831Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Salesforce Data Exfiltration](https://attack.mitre.org/campaigns/C0059), threat actors used [Tor](https://attack.mitre.org/software/S0183) IPs for voice calls and data collection.(Citation: Google Salesforce JUN 2025)", "external_references": [{"description": "Google Threat Intelligence Group. (2025, June 4). The Cost of a Call: From Voice Phishing to Data Extortion. Retrieved October 22, 2025.", "source_name": "Google Salesforce JUN 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/voice-phishing-data-extortion"}], "id": "relationship--f0a3c854-979e-4851-b665-4f3981d483fe", "modified": "2026-07-31T20:48:18.328Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--9cea8bec-07c5-422b-84b8-99d3128ce570", "spec_version": "2.1", "target_ref": "tool--ed7d0cb1-87a6-43b4-9f46-ef1bc56d6c68", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5687', 0, 79, '09-mitre-attack', 'retrieved', '0CEEAC5DADCCF841AB1E116C2724D5314ABDDFA04FB62B83120594624FD699DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
