VALUES ('doc-09-mitre-attack-p0-5689', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T17:57:03.957Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [APT28 Nearest Neighbor Campaign](https://attack.mitre.org/campaigns/C0051), [APT28](https://attack.mitre.org/groups/G0007) exfiltrated data over public-facing webservers – such as Google Drive.(Citation: Nearest Neighbor Volexity)", "external_references": [{"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "id": "relationship--1cde11ce-eef2-49e3-a42e-263bed74531f", "modified": "2026-07-31T21:11:45.965Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a010610e-22cb-437e-bfde-b78861bdca7a", "spec_version": "2.1", "target_ref": "attack-pattern--40597f16-0963-4249-bf4c-ac93b7fb9807", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5689', 0, 84, '09-mitre-attack', 'retrieved', 'DB2A988CE7DA2885774F89C9B2D6BC29A53FE1AA2DC8462979A272C20455A6E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
