VALUES ('doc-09-mitre-attack-p0-5693', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T17:52:19.363Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [APT28 Nearest Neighbor Campaign](https://attack.mitre.org/campaigns/C0051), [APT28](https://attack.mitre.org/groups/G0007) added rules to a victim''s Windows firewall to set up a series of port-forwards allowing traffic to target systems.(Citation: Nearest Neighbor Volexity)", "external_references": [{"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "id": "relationship--26a1086a-ce91-4e8e-a422-a96077e36969", "modified": "2026-07-31T21:11:46.029Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a010610e-22cb-437e-bfde-b78861bdca7a", "spec_version": "2.1", "target_ref": "attack-pattern--291ede6c-1473-454c-b614-5ac5ea63c987", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5693', 0, 93, '09-mitre-attack', 'retrieved', '03B0565429401DDA5C16C00C19C5E97558300364461EF7F3E53D5D3A8AD1CCFC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
