VALUES ('doc-09-mitre-attack-p0-5701', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T17:46:42.702Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [APT28 Nearest Neighbor Campaign](https://attack.mitre.org/campaigns/C0051), [APT28](https://attack.mitre.org/groups/G0007) used the following commands to dump SAM, SYSTEM, and SECURITY hives: reg save hklm\\sam, reg save hklm\\system, and reg save hklm\\security .(Citation: Nearest Neighbor Volexity) ", "external_references": [{"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "id": "relationship--ab5d6e11-8449-4170-b2a4-e7b67708b228", "modified": "2026-07-31T21:11:46.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a010610e-22cb-437e-bfde-b78861bdca7a", "spec_version": "2.1", "target_ref": "attack-pattern--1644e709-12d2-41e5-a60f-3470991f5011", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5701', 0, 97, '09-mitre-attack', 'retrieved', '56BFDDB0B66E783D09DA4548B96348884537478CE064F5BE35550927CD4F4FA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
