VALUES ('doc-09-mitre-attack-p0-5702', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T17:50:30.668Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [APT28 Nearest Neighbor Campaign](https://attack.mitre.org/campaigns/C0051), [APT28](https://attack.mitre.org/groups/G0007) used the native Microsoft utility [cipher.exe](https://attack.mitre.org/software/S1205) to securely wipe files and folders – overwriting the deleted data using cmd.exe /c cipher /W:C .(Citation: Nearest Neighbor Volexity) ", "external_references": [{"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "id": "relationship--c2fc39b7-17b5-4ca3-914a-7a5d03146c29", "modified": "2026-07-31T21:11:46.152Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a010610e-22cb-437e-bfde-b78861bdca7a", "spec_version": "2.1", "target_ref": "attack-pattern--fb640c43-aa6b-431e-a961-a279010424ac", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5702', 0, 98, '09-mitre-attack', 'retrieved', '453C32D3934FF46AD4CCC55B4A38DD842062FF3C9D4E8D752C1CE9178CE8A88D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
