VALUES ('doc-09-mitre-attack-p0-5720', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T16:22:53.167Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ArcaneDoor](https://attack.mitre.org/campaigns/C0046) utilized HTTP command and control traffic where commands are intercepted from HTTP traffic to the device, parsed for appropriate identifiers and commands, and then executed.(Citation: Cisco ArcaneDoor 2024)", "external_references": [{"description": "Cisco Talos. (2024, April 24). ArcaneDoor - New espionage-focused campaign found targeting perimeter network devices. Retrieved January 6, 2025.", "source_name": "Cisco ArcaneDoor 2024", "url": "https://blog.talosintelligence.com/arcanedoor-new-espionage-focused-campaign-found-targeting-perimeter-network-devices/"}], "id": "relationship--00806029-ec79-4337-a958-2afa3adabc1e", "modified": "2026-07-31T18:47:28.873Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a543ef15-91ea-4aa9-9c10-267d56e1ee82", "spec_version": "2.1", "target_ref": "attack-pattern--9c99724c-a483-4d60-ad9d-7f004e42e8e8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5720', 0, 85, '09-mitre-attack', 'retrieved', 'FF14FF0F3FA7411C8FA1FCDEC3FD4F885D4C7E1469D35B4043AEDE6D6B945D76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
