VALUES ('doc-09-mitre-attack-p0-5747', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T21:03:22.389Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries decoded a Base64-encoded ZIP archive using the built-in [certutil](https://attack.mitre.org/software/S0160).(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--00db4db6-fc7c-407b-81b5-11a3bdaac04f", "modified": "2026-07-31T20:48:19.391Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "tool--0a68f1f1-da74-4d28-8d9a-696c082706cc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5747', 0, 71, '09-mitre-attack', 'retrieved', 'C5BC279507D75F447C417471FFD43165C9FA5823A49971D2FD9C8CE6D63056FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
