VALUES ('doc-09-mitre-attack-p0-5759', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T21:01:01.007Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries utilized a Base64-encoded ZIP archive to prevent content analysis.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--49133c43-724f-41f8-a1de-2af251941311", "modified": "2026-07-31T20:48:19.603Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5759', 0, 71, '09-mitre-attack', 'retrieved', '86F31328B0598F91F8EC4937DD70C93AEE1396702D20CA1867D4E59C15D3846A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
