VALUES ('doc-09-mitre-attack-p0-5764', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T21:21:20.163Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries utilized the rsocx tool identified as `r.exe` and `rsocx.exe` to tunnel within the internal infrastructure using a Reverse SOCKS Proxy.(Citation: CERT Polska)(Citation: ESET DynoWiper Update JAN 2026)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}, {"description": "ESET. (2026, January 30). DynoWiper update: Technical analysis and attribution. Retrieved April 22, 2026.", "source_name": "ESET DynoWiper Update JAN 2026", "url": "https://www.welivesecurity.com/en/eset-research/dynowiper-update-technical-analysis-attribution/"}], "id": "relationship--5886efa7-c69d-4f66-949a-4979ca230f06", "modified": "2026-07-31T20:48:19.655Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--731f4f55-b6d0-41d1-a7a9-072a66389aea", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5764', 0, 110, '09-mitre-attack', 'retrieved', 'DCDEC9F895ABC11C2D361FFE2CCA46454FE1BE2D9A1DC0CAF004E7363F355B07', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
