VALUES ('doc-09-mitre-attack-p0-5783', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T20:28:20.804Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), threat actors leveraged the FortiGate VPN interface that was exposed to the internet to gain access to the victim environment.(Citation: CERT Polska)(Citation: Dragos ELECTRUM JAN 2026)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}, {"description": "https://5943619.hs-sites.com/hubfs/Reports/dragos-2025-poland-attack-report.pdf. (2026, January). ELECTRUM: CYBER ATTACK ON POLAND’S ELECTRIC SYSTEM 2025. Retrieved April 22, 2026.", "source_name": "Dragos ELECTRUM JAN 2026", "url": "https://5943619.hs-sites.com/hubfs/Reports/dragos-2025-poland-attack-report.pdf"}], "id": "relationship--98a10168-649c-4153-b321-e12a7df9010c", "modified": "2026-07-31T20:48:19.836Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--10d51417-ee35-4589-b1ff-b6df1c334e8d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5783', 0, 107, '09-mitre-attack', 'retrieved', '960B1E32D8270329CEE566760AAD787337812AD044D34B87DA3547B378E44036', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
