VALUES ('doc-09-mitre-attack-p0-5786', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T20:29:34.500Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), adversaries performed a factory-reset on compromised devices that hampered forensic investigations.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--a3ede3cc-37f1-4c57-bc2f-e1c65b25c578", "modified": "2026-07-31T20:48:19.866Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--f5bb433e-bdf6-4781-84bc-35e97e43be89", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5786', 0, 71, '09-mitre-attack', 'retrieved', '1C75E9F29F8B60A257E2FA683DAF1D602AE91C33BF443F46EF8CF55C685E150B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
