VALUES ('doc-09-mitre-attack-p0-5789', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T20:58:20.559Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries configured the FortiGate devices to send notifications to an attacker-controlled Slack channel. During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries had also staged tools and files on services such as Dropbox and Pastebin.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--a83255d3-38a5-49a0-998d-ba4720e28678", "modified": "2026-07-31T20:48:19.895Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--88d31120-5bc7-4ce3-a9c0-7cf147be8e54", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5789', 0, 95, '09-mitre-attack', 'retrieved', '25899E2362132345787F27A6FA251CD1ABA7F06B28F7EDA2ED62CE5ADDC68E99', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
