VALUES ('doc-09-mitre-attack-p0-5795', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T20:37:43.260Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries used [Tasklist](https://attack.mitre.org/software/S0057) for reconnaissance activities running `cmd.exe /c \"tasklist > C:\\Windows\\TEMP\\outlog.txt && netstat -nao >> C:\\Windows\\TEMP\\outlog.txt && netstat -r >> C:\\Windows\\TEMP\\ outlog.txt && arp -a >> C:\\Windows\\TEMP\\outlog.txt && dir /s /b C:\\ Users >> C:\\Windows\\TEMP\\outlog.txt`.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--cd424d91-ee2c-4a63-bbeb-e18cd4ed2d1d", "modified": "2026-07-31T20:48:19.967Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "tool--2e45723a-31da-4a7e-aaa6-e01998a6788f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5795', 0, 97, '09-mitre-attack', 'retrieved', '45E8C55B3067B6E107F44C4BC218F6AB13D68708CFAABD3926F2955F2F942141', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
