VALUES ('doc-09-mitre-attack-p0-5796', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T21:24:28.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries utilized Ping, the Advanced Port Scanner and Advanced IP Scanner to enumerate network devices.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--cf0143f0-1021-4825-9ad4-2a8803003ed9", "modified": "2026-07-31T20:48:19.975Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--e3a12395-188d-4051-9a16-ea8e14d07b88", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5796', 0, 76, '09-mitre-attack', 'retrieved', 'C2A1B7D00437AFB15806616603FFB4E9DD9A315C1F09F85851424CC430C3AB4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
