VALUES ('doc-09-mitre-attack-p0-5799', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T22:11:46.638Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DynoWiper](https://attack.mitre.org/software/S9038) was used for destructive attacks during the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063).(Citation: CERT Polska)(Citation: ESET DynoWiper JAN 2026)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}, {"description": "ESET. (2026, January 30). Russian Sandworm group attacks energy company in Poland with DynoWiper, ESET Research discovers. Retrieved April 22, 2026.", "source_name": "ESET DynoWiper JAN 2026", "url": "https://www.eset.com/us/about/newsroom/research/eset-research-russian-sandwormapt-attacks-energy-company-poland-with-dynowiper/"}], "id": "relationship--d2a0cc1b-10b4-4040-bd36-8856c064c7ae", "modified": "2026-07-31T20:48:19.999Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "malware--34057cb6-0a56-48a3-92e5-3af1357808da", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5799', 0, 99, '09-mitre-attack', 'retrieved', 'B83B11370BB4EE498F6082BEFF42549514D8BFEBEC990E49BFF83214F27D766D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
