VALUES ('doc-09-mitre-attack-p0-5808', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T21:09:32.673Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries dumped the entire Active Directory database by extracting the contents of the ntds.dit file.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--ed919b5f-3437-4955-96a0-8e1370adf7d1", "modified": "2026-07-31T20:48:20.103Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--edf91964-b26e-4b4a-9600-ccacd7d7df24", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5808', 0, 76, '09-mitre-attack', 'retrieved', 'C5290DE5731D94C4CAC55249F61D2B81499B49D19A2C1E77D2CBAEB199B784B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
