VALUES ('doc-09-mitre-attack-p0-5809', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T20:56:41.033Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries modified security settings within the victims Fortigate device, utilizing the native CLI. During the [2025 Poland Wiper Attacks](https://attack.mitre.org/campaigns/C0063), the adversaries also disabled network traffic logging.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--ffcd3051-8e23-4dd2-b71b-eb2c1bbf578b", "modified": "2026-07-31T20:48:20.127Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--a6aba167-5ada-4812-9da1-912c0e73335d", "spec_version": "2.1", "target_ref": "attack-pattern--a29aa77c-a88d-4f19-bab9-7751941b2e2d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5809', 0, 87, '09-mitre-attack', 'retrieved', '20235109AF275B10057C027DCFCE7F7B9DEA98B5494B9101FA32E8DA29C82C13', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
