VALUES ('doc-09-mitre-attack-p0-5815', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T18:08:06.399Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2016 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0025), DLLs and EXEs with filenames associated with common electric power sector protocols were used to masquerade files.(Citation: Dragos Crashoverride 2017)", "external_references": [{"description": "Dragos Inc.. (2017, June 13). CRASHOVERRIDE Analysis of the Threat to Electric Grid Operations. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2017", "url": "https://dragos.com/blog/crashoverride/CrashOverride-01.pdf"}], "id": "relationship--10976d43-afcf-44d5-bcbf-122f39e0cbff", "modified": "2026-07-31T21:05:25.538Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--aa73efef-1418-4dbe-b43c-87a498e97234", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5815', 0, 82, '09-mitre-attack', 'retrieved', '5894276C6D2A60C19E8623E085F4E4726B38FDE4941B8F51B210609F56921F91', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
