VALUES ('doc-09-mitre-attack-p0-5816', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T17:42:41.938Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2016 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0025), [Sandworm Team](https://attack.mitre.org/groups/G0034) used various MS-SQL stored procedures.(Citation: Dragos Crashoverride 2018)", "external_references": [{"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}], "id": "relationship--2542a753-4cfb-408f-98a8-e1b11f1bce10", "modified": "2026-07-31T21:05:25.585Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--aa73efef-1418-4dbe-b43c-87a498e97234", "spec_version": "2.1", "target_ref": "attack-pattern--f9e9365a-9ca2-4d9c-8e7c-050d73d1101a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5816', 0, 71, '09-mitre-attack', 'retrieved', 'C5ACA5F085248FB1502DBDD3C4D56398A4C3EA655A6537BFBFB903D70626500E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
