VALUES ('doc-09-mitre-attack-p0-5817', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T17:37:21.531Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2016 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0025), [Sandworm Team](https://attack.mitre.org/groups/G0034) added a login to a SQL Server with `sp_addlinkedsrvlogin`.(Citation: Dragos Crashoverride 2018)", "external_references": [{"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}], "id": "relationship--4f41a697-db81-4df8-8b46-a59d294112fa", "modified": "2026-07-31T21:05:25.718Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--aa73efef-1418-4dbe-b43c-87a498e97234", "spec_version": "2.1", "target_ref": "attack-pattern--e01be9c5-e763-4caf-aeb7-000b416aef67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5817', 0, 75, '09-mitre-attack', 'retrieved', '3D3EA08B6189551706F6D89F592CBDA5EB00470E1295F2CA55362F84C07C8F7B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
