VALUES ('doc-09-mitre-attack-p0-5825', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T17:40:05.224Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2016 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0025), [Sandworm Team](https://attack.mitre.org/groups/G0034) used UPX to pack a copy of [Mimikatz](https://attack.mitre.org/software/S0002).(Citation: Dragos Crashoverride 2018)", "external_references": [{"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}], "id": "relationship--998add45-ac31-4020-9179-5730f06ae9cd", "modified": "2026-07-31T21:05:26.076Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--aa73efef-1418-4dbe-b43c-87a498e97234", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5825', 0, 74, '09-mitre-attack', 'retrieved', 'ADA3BE7E6BF249E951E1D1BF6A62F8F2AF4615FAA6DF161CB1BDA750B99D878A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
