VALUES ('doc-09-mitre-attack-p0-5827', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T18:08:48.741Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2016 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0025), [Sandworm Team](https://attack.mitre.org/groups/G0034) used [Mimikatz](https://attack.mitre.org/software/S0002) to capture and use legitimate credentials.(Citation: Dragos Crashoverride 2018)", "external_references": [{"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}], "id": "relationship--b1b935ac-1823-48a8-ac16-b9d17e519475", "modified": "2026-07-31T21:05:26.246Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--aa73efef-1418-4dbe-b43c-87a498e97234", "spec_version": "2.1", "target_ref": "attack-pattern--65f2d882-3f41-4d48-8a06-29af77ec9f90", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5827', 0, 74, '09-mitre-attack', 'retrieved', '96253C1B298A5F0129B51E45FF1CD5AD5E7AD4FFD0A37F09708BCCF50926D690', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
