VALUES ('doc-09-mitre-attack-p0-5831', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T17:37:49.147Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2016 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0025), [Sandworm Team](https://attack.mitre.org/groups/G0034) created two new accounts, “admin” and “система” (System). The accounts were then assigned to a domain matching local operation and were delegated new privileges.(Citation: Dragos Crashoverride 2018)", "external_references": [{"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}], "id": "relationship--cf17ef95-3173-4bfd-be73-1cd920e8c2da", "modified": "2026-07-31T21:05:26.369Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--aa73efef-1418-4dbe-b43c-87a498e97234", "spec_version": "2.1", "target_ref": "attack-pattern--7610cada-1499-41a4-b3dd-46467b68d177", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5831', 0, 90, '09-mitre-attack', 'retrieved', '5C215A95607A15839C004C6CAE731A073B7545A4CAE8E000838CD51CCF2622FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
