VALUES ('doc-09-mitre-attack-p0-5836', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-04T20:40:33.293Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0010](https://attack.mitre.org/campaigns/C0010), UNC3890 actors likely compromised the domain of a legitimate Israeli shipping company.(Citation: Mandiant UNC3890 Aug 2022)", "external_references": [{"description": "Mandiant Israel Research Team. (2022, August 17). Suspected Iranian Actor Targeting Israeli Shipping, Healthcare, Government and Energy Sectors. Retrieved September 21, 2022.", "source_name": "Mandiant UNC3890 Aug 2022", "url": "https://www.mandiant.com/resources/blog/suspected-iranian-actor-targeting-israeli-shipping"}], "id": "relationship--57e9b366-fac5-4320-bb76-da81953de2dc", "modified": "2026-07-31T18:47:29.745Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ab747e62-1bcb-479f-a26b-1cd39d413d81", "spec_version": "2.1", "target_ref": "attack-pattern--f9cc4d06-775f-4ee1-b401-4e2cc0da30ba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5836', 0, 78, '09-mitre-attack', 'retrieved', 'D1D60A2065A49E236AAF9C52BC0F7083C1D760361D9D0BA779BA97087ABE50E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
