VALUES ('doc-09-mitre-attack-p0-5837', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-04T20:49:04.777Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [C0010](https://attack.mitre.org/campaigns/C0010), UNC3890 actors staged malware on their infrastructure for direct download onto a compromised system.(Citation: Mandiant UNC3890 Aug 2022) ", "external_references": [{"description": "Mandiant Israel Research Team. (2022, August 17). Suspected Iranian Actor Targeting Israeli Shipping, Healthcare, Government and Energy Sectors. Retrieved September 21, 2022.", "source_name": "Mandiant UNC3890 Aug 2022", "url": "https://www.mandiant.com/resources/blog/suspected-iranian-actor-targeting-israeli-shipping"}], "id": "relationship--634a14f9-e252-4f5e-851a-de8187de074e", "modified": "2026-07-31T18:47:29.772Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ab747e62-1bcb-479f-a26b-1cd39d413d81", "spec_version": "2.1", "target_ref": "attack-pattern--3ee16395-03f0-4690-a32e-69ce9ada0f9e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5837', 0, 81, '09-mitre-attack', 'retrieved', 'A2A7966770C1E4A57F876D81779B600313BE1D6287E59FCBF42B7B08B5990F31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
