VALUES ('doc-09-mitre-attack-p0-5839', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T20:42:14.985Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For [C0010](https://attack.mitre.org/campaigns/C0010), the threat actors compromised the login page of a legitimate Israeli shipping company and likely established a watering hole that collected visitor information.(Citation: Mandiant UNC3890 Aug 2022)", "external_references": [{"description": "Mandiant Israel Research Team. (2022, August 17). Suspected Iranian Actor Targeting Israeli Shipping, Healthcare, Government and Energy Sectors. Retrieved September 21, 2022.", "source_name": "Mandiant UNC3890 Aug 2022", "url": "https://www.mandiant.com/resources/blog/suspected-iranian-actor-targeting-israeli-shipping"}], "id": "relationship--8d172b4c-7732-4315-852a-958a1cd08025", "modified": "2026-07-31T18:47:29.806Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ab747e62-1bcb-479f-a26b-1cd39d413d81", "spec_version": "2.1", "target_ref": "attack-pattern--31fe0ba2-62fd-4fd9-9293-4043d84f7fe9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5839', 0, 89, '09-mitre-attack', 'retrieved', '744BB0B670B92DBDE04BE2D53C3F76A84032AC9BAA5C96F35C95C700B93B2BCC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
