VALUES ('doc-09-mitre-attack-p0-5913', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-28T09:56:45.813Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Versa Director Zero Day Exploitation](https://attack.mitre.org/campaigns/C0039) involved the development of a new web shell variant, [VersaMem](https://attack.mitre.org/software/S1154).(Citation: Lumen Versa 2024)", "external_references": [{"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "id": "relationship--d11ccc61-70e8-4921-b760-59e4df84934c", "modified": "2026-07-31T18:47:30.900Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--af0ec65a-caa9-40ef-b1c7-21b71fbf3a10", "spec_version": "2.1", "target_ref": "attack-pattern--212306d8-efa4-44c9-8c2d-ed3d2e224aa0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5913', 0, 73, '09-mitre-attack', 'retrieved', '06EB2293C23CC15727E5E34434ABBEA2BF4D2947E209991A2F9911903BA482A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
