VALUES ('doc-09-mitre-attack-p0-5916', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-27T18:36:08.398Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Versa Director Zero Day Exploitation](https://attack.mitre.org/campaigns/C0039) was conducted by [Volt Typhoon](https://attack.mitre.org/groups/G1017) between June and August 2024.(Citation: Lumen Versa 2024)", "external_references": [{"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "id": "relationship--b109514b-66b3-4c06-8b1d-4f89e1f2cfde", "modified": "2026-07-31T18:47:40.965Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "attributed-to", "revoked": false, "source_ref": "campaign--af0ec65a-caa9-40ef-b1c7-21b71fbf3a10", "spec_version": "2.1", "target_ref": "intrusion-set--174279b4-399f-4ddb-966e-5efedd1dd5f2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5916', 0, 73, '09-mitre-attack', 'retrieved', '5D51564411EAEF57B5195FE673D05DDCACAD553F0C618D896F3153EA4FCD5616', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
