VALUES ('doc-09-mitre-attack-p0-5953', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-13T17:48:15.590Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Wocao](https://attack.mitre.org/campaigns/C0014), threat actors used [dsquery](https://attack.mitre.org/software/S0105) to retrieve all subnets in the Active Directory.(Citation: FoxIT Wocao December 2019)", "external_references": [{"description": "Dantzig, M. v., Schamper, E. (2019, December 19). Operation Wocao: Shining a light on one of China’s hidden hacking groups. Retrieved October 8, 2020.", "source_name": "FoxIT Wocao December 2019", "url": "https://www.fox-it.com/media/kadlze5c/201912_report_operation_wocao.pdf"}], "id": "relationship--73137a74-58b1-4d45-b6dd-e8b4fbfe6236", "modified": "2026-07-31T18:47:31.670Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--b03d5112-e23a-4ac8-add0-be7502d24eff", "spec_version": "2.1", "target_ref": "tool--38952eac-cb1b-4a71-bad2-ee8223a1c8fe", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5953', 0, 81, '09-mitre-attack', 'retrieved', 'BC2C1E07C0FF93D8F58E8D3B5EC5425C205687B794BC8A8743A89CAF97AFC220', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
