VALUES ('doc-09-mitre-attack-p0-5957', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-27T16:22:30.103Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Wocao](https://attack.mitre.org/campaigns/C0014), threat actors encrypted IP addresses used for \"Agent\" proxy hops with RC4.(Citation: FoxIT Wocao December 2019)", "external_references": [{"description": "Dantzig, M. v., Schamper, E. (2019, December 19). Operation Wocao: Shining a light on one of China’s hidden hacking groups. Retrieved October 8, 2020.", "source_name": "FoxIT Wocao December 2019", "url": "https://www.fox-it.com/media/kadlze5c/201912_report_operation_wocao.pdf"}], "id": "relationship--80a8cd03-8f65-41fb-803a-64d92f9f1522", "modified": "2026-07-31T18:47:31.701Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--b03d5112-e23a-4ac8-add0-be7502d24eff", "spec_version": "2.1", "target_ref": "attack-pattern--ad255bfe-a9e6-4b52-a258-8d3462abe842", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5957', 0, 81, '09-mitre-attack', 'retrieved', 'B0342A30F7F85047B9E7DA1DA70625CC505091E22F467F219C582CD6734DC0FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
