VALUES ('doc-09-mitre-attack-p0-5961', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-27T16:35:21.894Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Wocao](https://attack.mitre.org/campaigns/C0014), threat actors used SMB to copy files to and from target systems.(Citation: FoxIT Wocao December 2019)", "external_references": [{"description": "Dantzig, M. v., Schamper, E. (2019, December 19). Operation Wocao: Shining a light on one of China’s hidden hacking groups. Retrieved October 8, 2020.", "source_name": "FoxIT Wocao December 2019", "url": "https://www.fox-it.com/media/kadlze5c/201912_report_operation_wocao.pdf"}], "id": "relationship--839d6bf7-6a63-48c0-8433-0d8d6c7ea61f", "modified": "2026-07-31T18:47:31.733Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--b03d5112-e23a-4ac8-add0-be7502d24eff", "spec_version": "2.1", "target_ref": "attack-pattern--bf90d72c-c00b-45e3-b3aa-68560560d4c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5961', 0, 81, '09-mitre-attack', 'retrieved', 'C8CD56004BF0F98FBC0289892B350624DAB269C27C4AFCE9F7CB99F4447A3C77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
