VALUES ('doc-09-mitre-attack-p0-5986', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-27T18:20:48.383Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [Operation Wocao](https://attack.mitre.org/campaigns/C0014), threat actors used `smbexec.py` and `psexec.py` from [Impacket](https://attack.mitre.org/software/S0357) for lateral movement.(Citation: FoxIT Wocao December 2019)", "external_references": [{"description": "Dantzig, M. v., Schamper, E. (2019, December 19). Operation Wocao: Shining a light on one of China’s hidden hacking groups. Retrieved October 8, 2020.", "source_name": "FoxIT Wocao December 2019", "url": "https://www.fox-it.com/media/kadlze5c/201912_report_operation_wocao.pdf"}], "id": "relationship--cbfd307e-ab23-49d0-bda0-83e883d4851a", "modified": "2026-07-31T18:47:31.920Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--b03d5112-e23a-4ac8-add0-be7502d24eff", "spec_version": "2.1", "target_ref": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-5986', 0, 80, '09-mitre-attack', 'retrieved', '8EFBA03C10BD5A8ED5352008A0457E008137BFC9689BC45133733517816A0B79', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
