VALUES ('doc-09-mitre-attack-p0-6035', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-04-10T19:00:01.414Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) used `SCHTASKS /Change` to modify legitimate scheduled tasks to run malicious code.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--20a9afe3-de36-428e-a054-cce863b2f4e9", "modified": "2026-07-31T21:12:31.040Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6035', 0, 82, '09-mitre-attack', 'retrieved', 'AB5BD9B971303CF9A49130EADFDC96A46380C1EE4BFE0D1594EF38F78D571063', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
