VALUES ('doc-09-mitre-attack-p0-6042', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-26T14:54:27.038Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) used the DUSTPAN in-memory dropper to drop a [Cobalt Strike](https://attack.mitre.org/software/S0154) BEACON backdoor onto a compromised network.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--5a7e12f1-a5e2-44bc-a244-c49688a816e7", "modified": "2026-07-31T21:12:31.279Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6042', 0, 86, '09-mitre-attack', 'retrieved', '10F610BB625ADCDA5441239EFCCB71E4D5463F7244F454D431FF3A749EF23581', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
