VALUES ('doc-09-mitre-attack-p0-6047', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-03T19:06:30.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) exfiltrated victim data via DNS lookups by encoding and prepending it as subdomains to the attacker-controlled domain.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--6c10da0b-4dfd-4389-b3e3-3599a2fab859", "modified": "2026-07-31T21:12:31.464Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "attack-pattern--fb8d023d-45be-47e9-bc51-f56bcae6435b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6047', 0, 87, '09-mitre-attack', 'retrieved', 'E7D1F6315249DBD07C76C39C0A27FB392792ECEB5FE1DB96E17BACB5EE68F3EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
