VALUES ('doc-09-mitre-attack-p0-6049', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-12-19T15:55:02.782Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) used multiple [dsquery](https://attack.mitre.org/software/S0105) commands to enumerate various Active Directory objects within a compromised environment.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--7230cc17-59e5-4d6a-9ce3-a17b358e2e94", "modified": "2026-07-31T21:12:31.510Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "tool--38952eac-cb1b-4a71-bad2-ee8223a1c8fe", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6049', 0, 84, '09-mitre-attack', 'retrieved', '5EBC816852E2578AF15CCBA76E905C090B744AEC78BE3F9530D4066D5EFB40D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
