VALUES ('doc-09-mitre-attack-p0-6054', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-12-13T21:03:18.538Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) used [Mimikatz](https://attack.mitre.org/software/S0002) to execute the `lsadump::sam` command on dumped registry hives to obtain locally stored credentials and NTLM hashes.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--80d4d084-46c0-481f-8827-66bfa2a7bbdd", "modified": "2026-07-31T21:12:31.705Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6054', 0, 89, '09-mitre-attack', 'retrieved', '1EC7D2CF8AF30FC22B7781362E9D3D8B9E7D4FFA5E01072031E5D51248E31B53', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
