VALUES ('doc-09-mitre-attack-p0-6059', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-03T19:16:21.206Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) used `cmd.exe` to execute reconnaissance commands.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--a686a939-b320-4326-bae1-8df65254ae46", "modified": "2026-07-31T21:12:33.474Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6059', 0, 76, '09-mitre-attack', 'retrieved', 'A7215C0843D43C4AE1D4969476C7C49B000A0B884A41B71184C47404B211A754', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
