VALUES ('doc-09-mitre-attack-p0-6062', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-03T19:01:08.241Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0017](https://attack.mitre.org/campaigns/C0017), [APT41](https://attack.mitre.org/groups/G0096) issued [Ping](https://attack.mitre.org/software/S0097) commands to trigger DNS resolutions for data exfiltration, where the output of a reconnaissance command was prepended to subdomains within [APT41](https://attack.mitre.org/groups/G0096)''s Cloudflare C2 infrastructure.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--c73c6a89-90d5-47e0-af58-b5197d4f3594", "modified": "2026-07-31T21:12:35.017Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--ba6dfa37-f401-4140-88b0-8938f2895e61", "spec_version": "2.1", "target_ref": "tool--b77b563c-34bb-4fb8-86a3-3694338f7b47", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6062', 0, 96, '09-mitre-attack', 'retrieved', 'ADE70CF988B2B8C255996157A9E109B448DDC850E3243E004C440B975BA0A31D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
