VALUES ('doc-09-mitre-attack-p0-6069', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-05-16T19:33:29.448Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0026](https://attack.mitre.org/campaigns/C0026), the threat actors re-registered expired [ANDROMEDA](https://attack.mitre.org/software/S1074) domains to profile past victims for further targeting.(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "id": "relationship--36f057c1-6f80-4254-963b-79704bbe6232", "modified": "2026-07-31T18:47:32.717Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--c89fa3ff-4773-4daf-8aec-d8f43f10116e", "spec_version": "2.1", "target_ref": "malware--dcd9548e-df9e-47c2-81f3-bc084289959d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6069', 0, 78, '09-mitre-attack', 'retrieved', '0846D258FC88CDE61CDB7F377EE875BB32D4B4BB14C541D9732E70834674EACF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
