VALUES ('doc-09-mitre-attack-p0-6070', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-25T20:25:18.433Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0026](https://attack.mitre.org/campaigns/C0026), the threat actors split encrypted archives containing stolen files and information into 3MB parts prior to exfiltration.(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "id": "relationship--42d043a1-0b6f-4acd-aea2-553579eb49c2", "modified": "2026-07-31T18:47:32.733Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--c89fa3ff-4773-4daf-8aec-d8f43f10116e", "spec_version": "2.1", "target_ref": "attack-pattern--c3888c54-775d-4b2f-b759-75a2ececcbfd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6070', 0, 81, '09-mitre-attack', 'retrieved', 'A7CC9C489D7902ECCB5D62350F0D33F64EBEA3146CE469729EF7117124638FDB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
