VALUES ('doc-09-mitre-attack-p0-6071', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-05-19T19:13:43.614Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0026](https://attack.mitre.org/campaigns/C0026), the threat actors re-registered a ClouDNS dynamic DNS subdomain which was previously used by [ANDROMEDA](https://attack.mitre.org/software/S1074).(Citation: Mandiant Suspected Turla Campaign February 2023)", "external_references": [{"description": "Hawley, S. et al. (2023, February 2). Turla: A Galaxy of Opportunity. Retrieved May 15, 2023.", "source_name": "Mandiant Suspected Turla Campaign February 2023", "url": "https://www.mandiant.com/resources/blog/turla-galaxy-opportunity"}], "id": "relationship--6d550704-4ccb-485b-8e79-519d13768afa", "modified": "2026-07-31T18:47:32.754Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--c89fa3ff-4773-4daf-8aec-d8f43f10116e", "spec_version": "2.1", "target_ref": "attack-pattern--7bd9c723-2f78-4309-82c5-47cad406572b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6071', 0, 79, '09-mitre-attack', 'retrieved', 'CB86EBAD0266E04AD53529844E67EC362CC4F163AFF965EF57BA0B68B1A67BEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
