VALUES ('doc-09-mitre-attack-p0-6092', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-22T19:53:44.711Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0027](https://attack.mitre.org/campaigns/C0027), [Scattered Spider](https://attack.mitre.org/groups/G1015) accessed victim SharePoint environments to search for VPN and MFA enrollment information, help desk instructions, and new hire guides.(Citation: Crowdstrike TELCO BPO Campaign December 2022)", "external_references": [{"description": "Parisi, T. (2022, December 2). Not a SIMulation: CrowdStrike Investigations Reveal Intrusion Campaign Targeting Telco and BPO Companies. Retrieved June 30, 2023.", "source_name": "Crowdstrike TELCO BPO Campaign December 2022", "url": "https://www.crowdstrike.com/blog/analysis-of-intrusion-campaign-targeting-telecom-and-bpo-companies/"}], "id": "relationship--7b2f6151-c019-4910-91a7-9dd6744c4ffb", "modified": "2026-07-31T18:47:33.509Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--df74f7ad-b10d-431c-9f1d-a2bc18dadefa", "spec_version": "2.1", "target_ref": "attack-pattern--0c4b4fda-9062-47da-98b9-ceae2dcf052a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6092', 0, 91, '09-mitre-attack', 'retrieved', 'D95C684C3D982E215C3ECB6D9D4940FBFF01D5C31545DEC2C8901E2A013055C1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
