VALUES ('doc-09-mitre-attack-p0-6095', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-07T18:30:12.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0027](https://attack.mitre.org/campaigns/C0027), [Scattered Spider](https://attack.mitre.org/groups/G1015) attempted to gain access by continuously sending MFA messages to the victim until they accept the MFA push challenge.(Citation: Crowdstrike TELCO BPO Campaign December 2022)", "external_references": [{"description": "Parisi, T. (2022, December 2). Not a SIMulation: CrowdStrike Investigations Reveal Intrusion Campaign Targeting Telco and BPO Companies. Retrieved June 30, 2023.", "source_name": "Crowdstrike TELCO BPO Campaign December 2022", "url": "https://www.crowdstrike.com/blog/analysis-of-intrusion-campaign-targeting-telecom-and-bpo-companies/"}], "id": "relationship--952ee3df-24da-4537-9e36-583e8f178f50", "modified": "2026-07-31T18:47:33.556Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--df74f7ad-b10d-431c-9f1d-a2bc18dadefa", "spec_version": "2.1", "target_ref": "attack-pattern--954a1639-f2d6-407d-aef3-4917622ca493", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6095', 0, 91, '09-mitre-attack', 'retrieved', 'B78CF22F1D9EA13068384360A5B5499CEF09BAF05DF6C0845F352418F64638A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
