VALUES ('doc-09-mitre-attack-p0-6105', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-30T14:16:30.385Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [C0027](https://attack.mitre.org/campaigns/C0027), [Scattered Spider](https://attack.mitre.org/groups/G1015) impersonated legitimate IT personnel in phone calls to direct victims to download a remote monitoring and management (RMM) tool that would allow the adversary to remotely control their system.(Citation: Crowdstrike TELCO BPO Campaign December 2022)", "external_references": [{"description": "Parisi, T. (2022, December 2). Not a SIMulation: CrowdStrike Investigations Reveal Intrusion Campaign Targeting Telco and BPO Companies. Retrieved June 30, 2023.", "source_name": "Crowdstrike TELCO BPO Campaign December 2022", "url": "https://www.crowdstrike.com/blog/analysis-of-intrusion-campaign-targeting-telecom-and-bpo-companies/"}], "id": "relationship--f417c73d-20a3-447c-8839-5897e01d2a90", "modified": "2026-07-31T18:47:33.726Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--df74f7ad-b10d-431c-9f1d-a2bc18dadefa", "spec_version": "2.1", "target_ref": "attack-pattern--bb5e59c4-abe7-40c7-8196-e373cb1e5974", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6105', 0, 101, '09-mitre-attack', 'retrieved', '2EBAF83AB127DE00FD974247B298E4FFBD283D724C069EB640C56C7134AD6298', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
