VALUES ('doc-09-mitre-attack-p0-6111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-27T20:06:56.105Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2022 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0034), [Sandworm Team](https://attack.mitre.org/groups/G0034) leveraged Scheduled Tasks through a Group Policy Object (GPO) to execute [CaddyWiper](https://attack.mitre.org/software/S0693) at a predetermined time.(Citation: Mandiant-Sandworm-Ukraine-2022)", "external_references": [{"description": "Ken Proska, John Wolfram, Jared Wilson, Dan Black, Keith Lunden, Daniel Kapellmann Zafra, Nathan Brubaker, Tyler Mclellan, Chris Sistrunk. (2023, November 9). Sandworm Disrupts Power in Ukraine Using a Novel Attack Against Operational Technology. Retrieved March 28, 2024.", "source_name": "Mandiant-Sandworm-Ukraine-2022", "url": "https://www.mandiant.com/resources/blog/sandworm-disrupts-power-ukraine-operational-technology"}], "id": "relationship--34ed3c2a-3e75-4c9c-966c-7fc33b92092e", "modified": "2026-07-31T21:11:05.233Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--df8eb785-70f8-4300-b444-277ba849083d", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6111', 0, 99, '09-mitre-attack', 'retrieved', '9ABB14B5C0E996F0E28C9E43A982D2CE45295A3391AFF4CF91ACB74C0138F2FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
