VALUES ('doc-09-mitre-attack-p0-6112', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-27T20:09:11.397Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2022 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0034), [Sandworm Team](https://attack.mitre.org/groups/G0034) configured Systemd to maintain persistence of GOGETTER, specifying the `WantedBy=multi-user.target` configuration to run GOGETTER when the system begins accepting user logins.(Citation: Mandiant-Sandworm-Ukraine-2022)", "external_references": [{"description": "Ken Proska, John Wolfram, Jared Wilson, Dan Black, Keith Lunden, Daniel Kapellmann Zafra, Nathan Brubaker, Tyler Mclellan, Chris Sistrunk. (2023, November 9). Sandworm Disrupts Power in Ukraine Using a Novel Attack Against Operational Technology. Retrieved March 28, 2024.", "source_name": "Mandiant-Sandworm-Ukraine-2022", "url": "https://www.mandiant.com/resources/blog/sandworm-disrupts-power-ukraine-operational-technology"}], "id": "relationship--41b9ea44-f258-4415-a3ba-d4b77be6cdc2", "modified": "2026-07-31T21:11:05.243Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--df8eb785-70f8-4300-b444-277ba849083d", "spec_version": "2.1", "target_ref": "attack-pattern--dfefe2ed-4389-4318-8762-f0272b350a1b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6112', 0, 104, '09-mitre-attack', 'retrieved', 'D878C744601313B870AEA53B032790209CD9BE007E95943A5FDE72DE3FDA5CB2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
