VALUES ('doc-09-mitre-attack-p0-6113', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-27T20:08:02.304Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the [2022 Ukraine Electric Power Attack](https://attack.mitre.org/campaigns/C0034), [Sandworm Team](https://attack.mitre.org/groups/G0034) deployed the Neo-REGEORG webshell on an internet-facing server.(Citation: Mandiant-Sandworm-Ukraine-2022)", "external_references": [{"description": "Ken Proska, John Wolfram, Jared Wilson, Dan Black, Keith Lunden, Daniel Kapellmann Zafra, Nathan Brubaker, Tyler Mclellan, Chris Sistrunk. (2023, November 9). Sandworm Disrupts Power in Ukraine Using a Novel Attack Against Operational Technology. Retrieved March 28, 2024.", "source_name": "Mandiant-Sandworm-Ukraine-2022", "url": "https://www.mandiant.com/resources/blog/sandworm-disrupts-power-ukraine-operational-technology"}], "id": "relationship--4e1b8403-d2ed-4d24-b7cd-2974ef9ba1d3", "modified": "2026-07-31T21:11:05.326Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--df8eb785-70f8-4300-b444-277ba849083d", "spec_version": "2.1", "target_ref": "attack-pattern--5d0d3609-d06d-49e1-b9c9-b544e0c618cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6113', 0, 91, '09-mitre-attack', 'retrieved', 'D131105F7BF12B1945F4612B8CF33D9A2B752D8B54439F931ACC03DCEE1CC605', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
