VALUES ('doc-09-mitre-attack-p0-6121', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-04T16:19:50.954Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quad7 Activity](https://attack.mitre.org/campaigns/C0055) has disabled the TP-Link management interface for TP-Link by killing the /usr/bin/httpd process.(Citation: Sekoia 7777 Botnet JUL 2024)(Citation: Microsoft Storm-0940)(Citation: Bitsight 7777 Botnet)", "external_references": [{"description": "Aime, F. et al. (n.d.). Solving the 7777 Botnet enigma: A cybersecurity quest. Retrieved July 23, 2024.", "source_name": "Sekoia 7777 Botnet JUL 2024", "url": "https://blog.sekoia.io/solving-the-7777-botnet-enigma-a-cybersecurity-quest/"}, {"description": "Batista, João. Gi7w0rm. (2024, August 27). Retrieved June 5, 2025.", "source_name": "Bitsight 7777 Botnet", "url": "https://www.bitsight.com/blog/7777-botnet-insights-multi-target-botnet"}, {"description": "Microsoft Threat Intelligence. (2024, October 31). Chinese threat actor Storm-0940 uses credentials from password spray attacks from a covert network. Retrieved June 4, 2025.", "source_name": "Microsoft Storm-0940", "url": "https://www.microsoft.com/en-us/security/blog/2024/10/31/chinese-threat-actor-storm-0940-uses-credentials-from-password-spray-attacks-from-a-covert-network/"}], "id": "relationship--04d2c81c-1140-4eea-8383-d835c80df3bf", "modified": "2026-07-31T18:47:33.910Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--e7511089-1076-4a3b-984d-1a0a8afe31e9", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6121', 0, 128, '09-mitre-attack', 'retrieved', '21C79