VALUES ('doc-09-mitre-attack-p0-6130', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-04T16:15:02.705Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quad7 Activity](https://attack.mitre.org/campaigns/C0055) has conducted a throttled variant of password spraying techniques that only utilized a single attempt to sign in within a 24-hour time period, eluding brute force detection thresholds.(Citation: Microsoft Storm-0940) ", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, October 31). Chinese threat actor Storm-0940 uses credentials from password spray attacks from a covert network. Retrieved June 4, 2025.", "source_name": "Microsoft Storm-0940", "url": "https://www.microsoft.com/en-us/security/blog/2024/10/31/chinese-threat-actor-storm-0940-uses-credentials-from-password-spray-attacks-from-a-covert-network/"}], "id": "relationship--71960517-1700-47ed-8abe-85c384458630", "modified": "2026-07-31T18:47:34.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--e7511089-1076-4a3b-984d-1a0a8afe31e9", "spec_version": "2.1", "target_ref": "attack-pattern--692074ae-bb62-4a5e-a735-02cb6bde458c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6130', 0, 93, '09-mitre-attack', 'retrieved', '9B4DB30357204A04AA5EC854A3A9DBC8511B4E217201391AFF5A3B7A588A8D30', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
