VALUES ('doc-09-mitre-attack-p0-6132', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-04T16:13:26.334Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quad7 Activity](https://attack.mitre.org/campaigns/C0055) has used non-standard TCP ports – such as 7777, 11288, 63256, 63210, 3256, and 3556 for C2.(Citation: Microsoft Storm-0940)(Citation: Sekoia 7777 Botnet JUL 2024)", "external_references": [{"description": "Aime, F. et al. (n.d.). Solving the 7777 Botnet enigma: A cybersecurity quest. Retrieved July 23, 2024.", "source_name": "Sekoia 7777 Botnet JUL 2024", "url": "https://blog.sekoia.io/solving-the-7777-botnet-enigma-a-cybersecurity-quest/"}, {"description": "Microsoft Threat Intelligence. (2024, October 31). Chinese threat actor Storm-0940 uses credentials from password spray attacks from a covert network. Retrieved June 4, 2025.", "source_name": "Microsoft Storm-0940", "url": "https://www.microsoft.com/en-us/security/blog/2024/10/31/chinese-threat-actor-storm-0940-uses-credentials-from-password-spray-attacks-from-a-covert-network/"}], "id": "relationship--946ccfa8-eef3-41f6-99ef-74d6caa817ce", "modified": "2026-07-31T18:47:34.134Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--e7511089-1076-4a3b-984d-1a0a8afe31e9", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6132', 0, 112, '09-mitre-attack', 'retrieved', '65C7CC98797816F9AD79086F0370AE2939C0FFB3A4D296266AA11A257BCB435C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
