VALUES ('doc-09-mitre-attack-p0-6134', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-04T16:20:49.255Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Quad7 Activity](https://attack.mitre.org/campaigns/C0055) has infected victim network devices by storing artifacts in the /tmp directory which is volatile in memory and will clear its contents upon shutdown or restart.(Citation: Bitsight 7777 Botnet)", "external_references": [{"description": "Batista, João. Gi7w0rm. (2024, August 27). Retrieved June 5, 2025.", "source_name": "Bitsight 7777 Botnet", "url": "https://www.bitsight.com/blog/7777-botnet-insights-multi-target-botnet"}], "id": "relationship--a23a8716-ffd4-407e-9890-99a416c35efa", "modified": "2026-07-31T18:47:34.177Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "campaign--e7511089-1076-4a3b-984d-1a0a8afe31e9", "spec_version": "2.1", "target_ref": "attack-pattern--02c5abff-30bf-4703-ab92-1f6072fae939", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6134', 0, 78, '09-mitre-attack', 'retrieved', '285416E860DBC51FA91A653131278CE15BC590A8E96B8ADAEBD61C5D564E7AF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
