VALUES ('doc-09-mitre-attack-p0-6160', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-12T14:18:38.906Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Network intrusion detection and prevention systems that use network signatures to identify traffic for specific adversary malware can be used to mitigate activity at the network level. Malware researchers can reverse engineer malware variants that use dynamic resolution and determine future C2 infrastructure that the malware will attempt to contact, but this is a time and resource intensive effort.(Citation: Cybereason Dissecting DGAs)(Citation: Cisco Umbrella DGA Brute Force)", "external_references": [{"description": "Sternfeld, U. (2016). Dissecting Domain Generation Algorithms: Eight Real World DGA Variants. Retrieved February 18, 2019.", "source_name": "Cybereason Dissecting DGAs", "url": "http://go.cybereason.com/rs/996-YZT-709/images/Cybereason-Lab-Analysis-Dissecting-DGAs-Eight-Real-World-DGA-Variants.pdf"}, {"description": "Kasza, A. (2015, February 18). Using Algorithms to Brute Force Algorithms. Retrieved February 18, 2019.", "source_name": "Cisco Umbrella DGA Brute Force", "url": "https://umbrella.cisco.com/blog/2015/02/18/at-high-noon-algorithms-do-battle/"}], "id": "relationship--0c2dadcb-36c4-4255-a53d-e54f1bb71c5f", "modified": "2026-04-29T14:23:05.920Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--12241367-a8b7-49b4-b86e-2236901ba50c", "spec_version": "2.1", "target_ref": "attack-pattern--7bd9c723-2f78-4309-82c5-47cad406572b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6160', 0, 144, '09-mitre-attack', 'retrieved', '36423AB5124FEBA14EFDE1784FC478D34FA092329B36D7820354E2