VALUES ('doc-09-mitre-attack-p0-6162', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T14:29:50.951Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Network intrusion detection and prevention systems that use network signatures to identify traffic for specific adversary malware can be used to mitigate activity at the network level. Signatures are often for unique indicators within protocols and may be based on the specific protocol used by a particular adversary or tool, and will likely be different across various malware families and versions. Adversaries will likely change tool C2 signatures over time or construct protocols in such a way as to avoid detection by common defensive tools. (Citation: University of Birmingham C2)", "external_references": [{"description": "Gardiner, J., Cova, M., Nagaraja, S. (2014, February). Command & Control Understanding, Denying and Detecting. Retrieved April 20, 2016.", "source_name": "University of Birmingham C2", "url": "https://arxiv.org/ftp/arxiv/papers/1408/1408.1136.pdf"}], "id": "relationship--1469ff36-c655-4513-8ffa-81dcb55c4ae6", "modified": "2026-04-29T14:23:05.932Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--12241367-a8b7-49b4-b86e-2236901ba50c", "spec_version": "2.1", "target_ref": "attack-pattern--f24faf46-3b26-4dbb-98f2-63460498e433", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6162', 0, 147, '09-mitre-attack', 'retrieved', '69A19AFFFDD3E1A975290280FCE1C9712E7CA5CA67AF3761B40F1E6CA6FC99A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
