VALUES ('doc-09-mitre-attack-p0-6165', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-15T15:37:47.733Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Network intrusion detection and prevention systems that use network signatures to identify traffic for specific adversary command and control infrastructure and malware can be used to mitigate activity at the network level. ", "id": "relationship--1a493d52-b97f-4cf3-a85b-1e9aaa66a410", "modified": "2026-04-29T14:23:05.940Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--12241367-a8b7-49b4-b86e-2236901ba50c", "spec_version": "2.1", "target_ref": "attack-pattern--fb8d023d-45be-47e9-bc51-f56bcae6435b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6165', 0, 62, '09-mitre-attack', 'retrieved', '85558D6AE0635E050ED750F36C39543B62893A05942534513C6B033B26D67C4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
