VALUES ('doc-09-mitre-attack-p0-6192', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T14:17:49.609Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Network intrusion detection and prevention systems that use network signatures to identify traffic for specific adversary malware can be used to mitigate some obfuscation activity at the network level.", "id": "relationship--82cf0b15-1cd0-4539-b3fe-63ee4d379113", "modified": "2026-04-29T14:23:06.104Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--12241367-a8b7-49b4-b86e-2236901ba50c", "spec_version": "2.1", "target_ref": "attack-pattern--ad255bfe-a9e6-4b52-a258-8d3462abe842", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6192', 0, 58, '09-mitre-attack', 'retrieved', 'C0B9C503F79B961FEF7F5D4386879C89ECBDF3F24ABC7B5F8F9F00CEE58C4118', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
