VALUES ('doc-09-mitre-attack-p0-6211', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T15:13:50.808Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Network intrusion detection and prevention systems that use network signatures may be able to prevent traffic to remote access services.", "id": "relationship--d5c70727-794c-4404-b30d-0d798a62ad64", "modified": "2026-04-29T14:23:06.217Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--12241367-a8b7-49b4-b86e-2236901ba50c", "spec_version": "2.1", "target_ref": "attack-pattern--4061e78c-1284-44b4-9116-73e4ac3912f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6211', 0, 49, '09-mitre-attack', 'retrieved', '56BEDEE61BC0B101CF89079E8264AC032F5F76E6AB282B57BEBA0B910F2CBFC4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
