VALUES ('doc-09-mitre-attack-p0-6224', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-28T01:37:57.431Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit access to network infrastructure and resources that can be used to reshape traffic or otherwise produce AiTM conditions.", "id": "relationship--0f9283d3-3b13-47ca-9757-7a7739738356", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--1dcaeb21-9348-42ea-950a-f842aaf1ae1f", "spec_version": "2.1", "target_ref": "attack-pattern--035bb001-ab69-4a0b-9f6c-2de8b09e1b9d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6224', 0, 48, '09-mitre-attack', 'retrieved', '36D84EF0488F3F0A8607A52F5CDE03EC22FD0FFA64D45094C0FB21F10669F0F5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
