VALUES ('doc-09-mitre-attack-p0-6227', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-30T17:54:04.068Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit communications with the container service to local Unix sockets or remote access via SSH. Require secure port access to communicate with the APIs over TLS by disabling unauthenticated access to the Docker API on port 2375. Instead, communicate with the Docker API over TLS on port 2376.(Citation: Docker Daemon Socket Protect)", "external_references": [{"description": "Docker. (n.d.). Protect the Docker Daemon Socket. Retrieved March 29, 2021.", "source_name": "Docker Daemon Socket Protect", "url": "https://docs.docker.com/engine/security/protect-access/"}], "id": "relationship--1720444b-e442-423e-ba6f-48079ad8b04e", "modified": "2026-04-29T14:23:05.936Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--1dcaeb21-9348-42ea-950a-f842aaf1ae1f", "spec_version": "2.1", "target_ref": "attack-pattern--800f9819-7007-4540-a520-40e655876800", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6227', 0, 101, '09-mitre-attack', 'retrieved', 'A03311E8BCA5B6A639B4DCD3293FD3E8E007B29A929E247B9305470F528CD348', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
