VALUES ('doc-09-mitre-attack-p0-6229', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T17:27:56.529Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent unnecessary remote access to file shares, hypervisors, sensitive systems, etc. Mechanisms to limit access may include use of network concentrators, RDP gateways, etc.(Citation: Sygnia ESXi Ransomware 2024)", "external_references": [{"description": "Nital Ruzin and Omer Kidron. (2024, May 15). ESXi Ransomware Attacks: Evolution, Impact, and Defense Strategy. Retrieved April 4, 2025.", "source_name": "Sygnia ESXi Ransomware 2024", "url": "https://www.sygnia.co/blog/esxi-ransomware-attacks/"}], "id": "relationship--3a062b27-636e-4164-9156-65631d140765", "modified": "2026-04-29T14:23:05.999Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--1dcaeb21-9348-42ea-950a-f842aaf1ae1f", "spec_version": "2.1", "target_ref": "attack-pattern--54a649ff-439a-41a4-9856-8d144a2551ba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6229', 0, 86, '09-mitre-attack', 'retrieved', '7FF09BDFC888D7ECA485F380F3F617C69232F445EEE5145D50645844EF88EFB1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
