VALUES ('doc-09-mitre-attack-p0-6230', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-25T14:33:33.700Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Establish network access control policies, such as using device certificates and the 802.1x standard. (Citation: Wikipedia 802.1x) Restrict use of DHCP to registered devices to prevent unregistered devices from communicating with trusted systems.", "external_references": [{"description": "Wikipedia. (2018, March 30). IEEE 802.1X. Retrieved April 11, 2018.", "source_name": "Wikipedia 802.1x", "url": "https://en.wikipedia.org/wiki/IEEE_802.1X"}], "id": "relationship--64af911e-0b75-45b5-903d-b1ab4676556f", "modified": "2026-04-29T14:23:06.062Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--1dcaeb21-9348-42ea-950a-f842aaf1ae1f", "spec_version": "2.1", "target_ref": "attack-pattern--d40239b3-05ff-46d8-9bdd-b46d13463ef9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6230', 0, 79, '09-mitre-attack', 'retrieved', '4184E9E39716323920D8A595E7CAEBD0781AF59A853A81A17B920B68930E897F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
