VALUES ('doc-09-mitre-attack-p0-6232', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-31T14:01:52.505Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit communications with the container service to managed and secured channels, such as local Unix sockets or remote access via SSH. Require secure port access to communicate with the APIs over TLS by disabling unauthenticated access to the Docker API and Kubernetes API Server.(Citation: Docker Daemon Socket Protect)(Citation: Kubernetes API Control Access) In Kubernetes clusters deployed in cloud environments, use native cloud platform features to restrict the IP ranges that are permitted to access to API server.(Citation: Kubernetes Cloud Native Security) Where possible, consider enabling just-in-time (JIT) access to the Kubernetes API to place additional restrictions on access.(Citation: Microsoft AKS Azure AD 2023)", "external_references": [{"description": "Docker. (n.d.). Protect the Docker Daemon Socket. Retrieved March 29, 2021.", "source_name": "Docker Daemon Socket Protect", "url": "https://docs.docker.com/engine/security/protect-access/"}, {"description": "Kubernetes. (n.d.). Overview of Cloud Native Security. Retrieved March 8, 2023.", "source_name": "Kubernetes Cloud Native Security", "url": "https://kubernetes.io/docs/concepts/security/overview/"}, {"description": "Microsoft. (2023, February 27). AKS-managed Azure Active Directory integration. Retrieved March 8, 2023.", "source_name": "Microsoft AKS Azure AD 2023", "url": "https://learn.microsoft.com/en-us/azure/aks/managed-aad"}, {"description": "The Kubernetes Authors. (n.d.). Controlling Access to The Kubernetes API. Retrieved March 29, 2021.", "source_name": "Kubernetes API Control Access", "url": "https://kubernetes.io/docs/concepts/security/controlling-access/"}], "id": "relationship--9d62760d-5678-4ebf-9a19-aa9de5d9728c", "modified": "2026-04-29T14:23:06.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--1dcaeb21-9348-42ea-950a-f842aaf1ae1f", "spec_version": "2.1", "target_ref": "attack-pattern--f8ef3a62-3f44-40a4-abca-761ab235c436", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6232', 0, 215, '09-mitre-attack', 'retrieved', '85A3D4934D70A022801CB734EE442963097D07947DF978E3F4A15821DE40D506', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
