VALUES ('doc-09-mitre-attack-p0-6242', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-13T16:43:14.999Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Encryption and off-system storage of sensitive information may be one way to mitigate collection of files, but may not stop an adversary from acquiring the information if an intrusion persists over a long period of time and the adversary is able to discover and access the data through other means.", "id": "relationship--4df90c69-8ac5-4f22-b0cf-dd4debb8e051", "modified": "2026-04-29T14:23:06.031Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20a2baeb-98c2-4901-bad7-dc62d0a03dea", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6242', 0, 79, '09-mitre-attack', 'retrieved', '4AF284FF44D3FB764F54B5031FCA9B73A96444577A3DA327CBB109E162E05D2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
