VALUES ('doc-09-mitre-attack-p0-6251', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T17:26:42.107Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If the application deployment system can be configured to deploy only signed binaries, then ensure that the trusted signing certificates are not co-located with the application deployment system and are instead located on a system that cannot be accessed remotely or to which remote access is tightly controlled.", "id": "relationship--e4236234-0fd7-426f-b55a-d32364e3a64e", "modified": "2026-04-29T14:23:06.236Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20a2baeb-98c2-4901-bad7-dc62d0a03dea", "spec_version": "2.1", "target_ref": "attack-pattern--92a78814-b191-47ca-909c-1ccfe3777414", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6251', 0, 77, '09-mitre-attack', 'retrieved', '808F36A9CBDE4F49528D4B696804B1ECAAF684E22925C921AE0E2D8259D5A2BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
