VALUES ('doc-09-mitre-attack-p0-6252', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-01T18:23:25.245Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Mitigation of some variants of this technique could be achieved through the use of stateful firewalls, depending upon how it is implemented.", "id": "relationship--0058d5dd-bf42-4a09-94ff-dfb024b949df", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--8868cb5b-d575-4a60-acb2-07d37389a2fd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6252', 0, 51, '09-mitre-attack', 'retrieved', '57A5F7E228256BC32A531EA3156757499D2457FF970950ECA4F7C7A815D4B019', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
