VALUES ('doc-09-mitre-attack-p0-6254', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-15T16:03:39.245Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider filtering network traffic to untrusted or known bad domains and resources. ", "id": "relationship--0927eb00-4a08-4ed1-8678-84d6e1e87b98", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--4fe28b27-b13c-453e-a386-c2ef362a573b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6254', 0, 42, '09-mitre-attack', 'retrieved', 'C40F2F6C5EF9891A3EB910E0F6B18C5BAF11A65D33402AF12A921FB305F7A211', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
