INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6256', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-24T18:52:46.018Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict outbound network traffic from public-facing servers to prevent unauthorized connections from initiating communications with attacker-controlled infrastructure. While this may not prevent the initial exploitation, it limits the attacker''s ability to verify and control the compromised server post-exploit, reducing the overall impact of the attack.", "id": "relationship--1c0c0c90-7974-48f4-9de0-15a8d9b00e0a", "modified": "2026-04-29T14:23:05.943Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6256', 0, 74, '09-mitre-attack', 'retrieved', '61F671669D2101FC98ABD17CFFA1F2BCD4050E21CD087486CC09FB4656EC5EC3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
