VALUES ('doc-09-mitre-attack-p0-6262', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-13T16:47:56.005Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Modify network and/or host firewall rules, as well as other network controls, to only allow legitimate BITS traffic.", "id": "relationship--4b4d8f9e-a416-4af6-9c20-582892601668", "modified": "2026-04-29T14:23:06.028Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--c8e87b83-edbb-48d4-9295-4974897525b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6262', 0, 47, '09-mitre-attack', 'retrieved', '941FA4718D193E0BB6179C283664E10C336CCF19581B8144BD09FF9372318622', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
