VALUES ('doc-09-mitre-attack-p0-6263', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-18T17:11:15.628Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Mitigation of some variants of this technique could be achieved through the use of stateful firewalls, depending upon how it is implemented.", "id": "relationship--4b5e8e16-ddf4-4339-859b-f70f980d612b", "modified": "2026-04-29T14:23:06.028Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--451a9977-d255-43c9-b431-66de80130c8c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6263', 0, 51, '09-mitre-attack', 'retrieved', 'AE4556F9D7631399A016AB2ED64625732ACE0BFC5C9B1DB8D5B1564CD37C3CE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
