VALUES ('doc-09-mitre-attack-p0-6264', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-15T15:30:42.478Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce proxies and use dedicated servers for services such as DNS and only allow those systems to communicate over respective ports/protocols, instead of all systems within a network. ", "id": "relationship--4c8d1c47-d1a1-4117-8ba5-39296d8afe4d", "modified": "2026-04-29T14:23:06.030Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--79a4052e-1a89-4b09-aea6-51f1d11fe19c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6264', 0, 58, '09-mitre-attack', 'retrieved', '9A9EEDF8CBFB8B4603689ED59A7F3D9EF8D684558C91136A623385E32B3DB6A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
