VALUES ('doc-09-mitre-attack-p0-6268', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-10T13:59:38.601Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider modifying host firewall rules to prevent egress traffic from verclsid.exe.", "id": "relationship--54add4d1-ab65-451e-b3ab-2c045261b082", "modified": "2026-04-29T14:23:06.041Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--808e6329-ca91-4b87-ac2d-8eadc5f8f327", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6268', 0, 40, '09-mitre-attack', 'retrieved', 'BC64D8C83975A91E9E9AD5848E1477B2CE6EF90663C27C746F8E0F53FACE6B88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
