VALUES ('doc-09-mitre-attack-p0-6269', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T15:31:43.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Leverage services provided by Content Delivery Networks (CDN) or providers specializing in DoS mitigations to filter traffic upstream from services.(Citation: CERT-EU DDoS March 2017) Filter boundary traffic by blocking source addresses sourcing the attack, blocking ports that are being targeted, or blocking protocols being used for transport.", "external_references": [{"description": "Meintanis, S., Revuelto, V., Socha, K.. (2017, March 10). DDoS Overview and Response Guide. Retrieved April 24, 2019.", "source_name": "CERT-EU DDoS March 2017", "url": "http://cert.europa.eu/static/WhitePapers/CERT-EU_Security_Whitepaper_DDoS_17-003.pdf"}], "id": "relationship--5c8cea6d-46d9-4a66-a23e-047dd02f756b", "modified": "2026-04-29T14:23:06.051Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--38eb0c22-6caf-46ce-8869-5964bd735858", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6269', 0, 103, '09-mitre-attack', 'retrieved', '9FF6C4D4F69109D56999CBE1FD2096485BDA873192EE16DF9EC0D07D5640D101', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
