VALUES ('doc-09-mitre-attack-p0-6271', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-01T13:16:32.965Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider using the host firewall to restrict file sharing communications such as SMB. (Citation: Microsoft Preventing SMB)", "external_references": [{"description": "Microsoft. (2020, March 10). Preventing SMB traffic from lateral connections and entering or leaving the network. Retrieved June 1, 2020.", "source_name": "Microsoft Preventing SMB", "url": "https://support.microsoft.com/en-us/help/3185535/preventing-smb-traffic-from-lateral-connections"}], "id": "relationship--6485bfc6-53b5-43c1-9c52-6a35c3fc630d", "modified": "2026-04-29T14:23:06.061Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--bf90d72c-c00b-45e3-b3aa-68560560d4c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6271', 0, 74, '09-mitre-attack', 'retrieved', '2DD98E82AA83289D0BF8BE3CBA99B602ECC03826DE65D52838653E4A17BD3ADF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
