VALUES ('doc-09-mitre-attack-p0-6276', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-18T17:42:08.974Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Properly configure firewalls, application firewalls, and proxies to limit outgoing traffic to sites and services used by remote access software.", "id": "relationship--80a23356-20b7-49a3-a48e-e0c04e2bff86", "modified": "2026-04-29T14:23:06.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--4061e78c-1284-44b4-9116-73e4ac3912f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6276', 0, 49, '09-mitre-attack', 'retrieved', '96D23C4ABDB58B941A0E057C51CF97A0A7F14176DAC3E2306A73C690A76A20A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
