INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6277', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T19:53:23.769Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\nBlock SMB traffic from exiting an enterprise network with egress filtering or by blocking TCP ports 139, 445 and UDP port 137. Filter or block WebDAV protocol traffic from exiting the network. If access to external resources over SMB and WebDAV is necessary, then traffic should be tightly limited with allowlisting. (Citation: US-CERT SMB Security) (Citation: US-CERT APT Energy Oct 2017)", "external_references": [{"description": "US-CERT. (2017, March 16). SMB Security Best Practices. Retrieved December 21, 2017.", "source_name": "US-CERT SMB Security", "url": "https://www.us-cert.gov/ncas/current-activity/2017/01/16/SMB-Security-Best-Practices"}, {"description": "US-CERT. (2017, October 20). Alert (TA17-293A): Advanced Persistent Threat Activity Targeting Energy and Other Critical Infrastructure Sectors. Retrieved November 2, 2017.", "source_name": "US-CERT APT Energy Oct 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-293A"}], "id": "relationship--85c9285a-6738-42dd-aa12-fbded3e7bbdb", "modified": "2026-04-29T14:23:06.108Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--b77cf5f3-6060-475d-bd60-40ccbf28fdc2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6277', 0, 140, '09-mitre-attack', 'retrieved', '850054DD00CD525F1187346C05A4E0420CECBBB546FFD27A36BC85C8991C4709', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
