INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6278', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-19T17:10:51.734Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Mitigation of some variants of this technique could be achieved through the use of stateful firewalls, depending upon how it is implemented.", "id": "relationship--8bcfefd1-20c7-4784-ae07-3e693ecff605", "modified": "2026-04-29T14:23:06.116Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--005cc321-08ce-4d17-b1ea-cb5275926520", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6278', 0, 51, '09-mitre-attack', 'retrieved', '2C7DDC30AB7E845DD246182A992587F0C88FF347EF14DD3B76BA1EC05378D61E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
