VALUES ('doc-09-mitre-attack-p0-6280', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-20T17:30:35.053Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Apply extended ACLs to block unauthorized protocols outside the trusted network.(Citation: US-CERT TA17-156A SNMP Abuse 2017)", "external_references": [{"description": "US-CERT. (2017, June 5). Reducing the Risk of SNMP Abuse. Retrieved October 19, 2020.", "source_name": "US-CERT TA17-156A SNMP Abuse 2017", "url": "https://us-cert.cisa.gov/ncas/alerts/TA17-156A"}], "id": "relationship--940764df-0039-40fa-a3c7-ce064ceed4ea", "modified": "2026-04-29T14:23:06.127Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--52759bf1-fe12-4052-ace6-c5b0cf7dd7fd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6280', 0, 69, '09-mitre-attack', 'retrieved', '71F4FAC72DB829DE4418E9FF1CB964A7B967D64D457DE7F428F31387F7509FEF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
