VALUES ('doc-09-mitre-attack-p0-6282', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-24T22:26:58.697Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Properly configure firewalls, application firewalls, and proxies to limit outgoing traffic to sites and services used by remote access software.", "id": "relationship--98fb9ba2-df83-48d5-a962-7de7070d567f", "modified": "2026-04-29T14:23:06.134Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--d4287702-e2f7-4946-bdfa-2c7f5aaa5032", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6282', 0, 49, '09-mitre-attack', 'retrieved', '2963E3791EFA2700355CDCAAD7312B301020370826E0B935EDFFB108C640011A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
