VALUES ('doc-09-mitre-attack-p0-6285', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-28T14:20:33.755Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider filtering publish/subscribe protocol requests to untrusted or known bad resources over irregular ports (e.g. MQTT’s standard ports are 1883 or 8883).", "id": "relationship--9f0abcfc-68b7-4e6c-9b9c-e511fdd2db00", "modified": "2026-04-29T14:23:06.142Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--241f9ea8-f6ae-4f38-92f5-cef5b7e539dd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6285', 0, 51, '09-mitre-attack', 'retrieved', 'E09D05C6C4DAEB716267A20C3013E4AF1EF38B94636BD6A1E366F7765071DC63', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
