VALUES ('doc-09-mitre-attack-p0-6288', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-11T15:46:13.715Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement network-based filtering restrictions to prohibit data transfers to untrusted VPCs.", "id": "relationship--a5b61b67-8d99-4bc5-86d0-00739f0be666", "modified": "2026-04-29T14:23:06.151Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--d4bdbdea-eaec-4071-b4f9-5105e12ea4b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6288', 0, 40, '09-mitre-attack', 'retrieved', '6607CC1E571A7FB5020BFBD8DEDA57266D2276101C00E1E3DA2ECD03D1C6714B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
