VALUES ('doc-09-mitre-attack-p0-6289', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T23:49:08.663Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Apply extended ACLs to block unauthorized protocols outside the trusted network.(Citation: US-CERT TA17-156A SNMP Abuse 2017)", "external_references": [{"description": "US-CERT. (2017, June 5). Reducing the Risk of SNMP Abuse. Retrieved October 19, 2020.", "source_name": "US-CERT TA17-156A SNMP Abuse 2017", "url": "https://us-cert.cisa.gov/ncas/alerts/TA17-156A"}], "id": "relationship--a78cac98-60e1-406a-8486-fcaf04a644e3", "modified": "2026-04-29T14:23:06.153Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--0ad7bc5c-235a-4048-944b-3b286676cb74", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6289', 0, 69, '09-mitre-attack', 'retrieved', 'D2E36F4C5286962ECF6C7934675E83AB2519C7D6539C30C7081943D50F4B9025', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
