VALUES ('doc-09-mitre-attack-p0-6290', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:08:29.990Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Upon identifying a compromised network device being used to bridge a network boundary, block the malicious packets using an unaffected network device in path, such as a firewall or a router that has not been compromised. Continue to monitor for additional activity and to ensure that the blocks are indeed effective.", "id": "relationship--ac04879c-2316-4c3c-86e4-8fac1e80fb49", "modified": "2026-04-29T14:23:06.159Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--b8017880-4b1e-42de-ad10-ae7ac6705166", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6290', 0, 80, '09-mitre-attack', 'retrieved', '1AC68986D0A4CD5C1470FB0CC535DD992E99B1161871FDFA94833984D7F9BE8D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
