VALUES ('doc-09-mitre-attack-p0-6296', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T23:54:29.945Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Apply extended ACLs to block unauthorized protocols outside the trusted network.(Citation: US-CERT TA17-156A SNMP Abuse 2017)", "external_references": [{"description": "US-CERT. (2017, June 5). Reducing the Risk of SNMP Abuse. Retrieved October 19, 2020.", "source_name": "US-CERT TA17-156A SNMP Abuse 2017", "url": "https://us-cert.cisa.gov/ncas/alerts/TA17-156A"}], "id": "relationship--eaa4e3f4-e3f6-4c1e-9cbf-4801028abfea", "modified": "2026-04-29T14:23:06.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--ee7ff928-801c-4f34-8a99-3df965e581a5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6296', 0, 69, '09-mitre-attack', 'retrieved', 'D0D8F1E84D48CFFD59AD2CAA0FD8A79D1B7C60F16252671FD073B1EA665205C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
