VALUES ('doc-09-mitre-attack-p0-6297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T15:13:33.503Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use network appliances to filter ingress or egress traffic and perform protocol-based filtering. Configure software on endpoints to filter network traffic.", "id": "relationship--ee0f724e-6622-40db-8a31-82fb6b361e0b", "modified": "2026-04-29T14:23:06.249Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--355be19c-ffc9-46d5-8d50-d6a036c675b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6297', 0, 50, '09-mitre-attack', 'retrieved', 'E4E77E69F3137E27E233ED351BA621C53BFBC79B3564031EE518B393B290448A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
