VALUES ('doc-09-mitre-attack-p0-6298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:48:08.498Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Block Traffic\tUpon identifying a compromised network device being used to bridge a network boundary, block the malicious packets using an unaffected network device in path, such as a firewall or a router that has not been compromised. Continue to monitor for additional activity and to ensure that the blocks are indeed effective.", "id": "relationship--f03e2a94-27c6-470f-9f87-7cac3c6845af", "modified": "2026-04-29T14:23:06.252Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--4ffc1794-ec3b-45be-9e52-42dbcb2af2de", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6298', 0, 81, '09-mitre-attack', 'retrieved', '2CF8306E956C86DF743C1F1EDAD7D39D05D94BDAE48C379BE509593971AF6B7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
