VALUES ('doc-09-mitre-attack-p0-6300', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-17T20:44:54.835Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit access to the Instance Metadata API. A properly configured Web Application Firewall (WAF) may help prevent external adversaries from exploiting Server-side Request Forgery (SSRF) attacks that allow access to the Cloud Instance Metadata API.(Citation: RedLock Instance Metadata API 2018)", "external_references": [{"description": "Higashi, Michael. (2018, May 15). Instance Metadata API: A Modern Day Trojan Horse. Retrieved July 16, 2019.", "source_name": "RedLock Instance Metadata API 2018", "url": "https://redlock.io/blog/instance-metadata-api-a-modern-day-trojan-horse"}], "id": "relationship--fce13b14-c974-4de2-9dfb-7ad45bca85f0", "modified": "2026-04-29T14:23:06.269Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--20f6a9df-37c4-4e20-9e47-025983b1b39d", "spec_version": "2.1", "target_ref": "attack-pattern--19bf235b-8620-4997-b5b4-94e0659ed7c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6300', 0, 96, '09-mitre-attack', 'retrieved', 'D36E39127167432A32D2572072C61885674FE82BD8CE463FEA7A8AC08CCF5898', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
