VALUES ('doc-09-mitre-attack-p0-6301', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-01T21:33:59.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider blocking download/transfer and execution of potentially uncommon file types known to be used in adversary campaigns.", "id": "relationship--0005fb3b-274a-4ac1-8fb2-51366fcd1a6b", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--43c9bc06-715b-42db-972f-52d25c09a20c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6301', 0, 46, '09-mitre-attack', 'retrieved', 'FAFD7CB0B7A6DB23D6CC200C08653B2AACC0F4897A6076D080BBD9CE5766D067', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
