VALUES ('doc-09-mitre-attack-p0-6302', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-14T22:34:03.212Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Web proxies can be used to enforce external network communication policy that prevents use of unauthorized external services.", "id": "relationship--0d57e872-1062-4bab-b3c5-3cea17cba4dc", "modified": "2026-04-29T14:23:05.921Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6302', 0, 47, '09-mitre-attack', 'retrieved', 'AAAAD41D383B44CA465D28AAF2FD386BC3240A59E0A444AA3C5D6101DE18D8A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
