VALUES ('doc-09-mitre-attack-p0-6303', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-02T19:18:20.216Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Determine if certain websites that can be used for spearphishing are necessary for business operations and consider blocking access if activity cannot be monitored well or if it poses a significant risk.", "id": "relationship--239092bc-09e4-4c16-9d83-071929c9e4a4", "modified": "2026-04-29T14:23:05.953Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--2b742742-28c3-4e1b-bab7-8350d6300fa7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6303', 0, 61, '09-mitre-attack', 'retrieved', '745A579659BBBA836F921AFAE1535E9CC310799EF281CDBFC62310C55A82FE4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
