VALUES ('doc-09-mitre-attack-p0-6305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-08T14:46:20.140Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict or block web-based content that could be used to extract session cookies or credentials stored in browsers. Use browser security settings, such as disabling third-party cookies and restricting browser extensions, to limit the attack surface.", "id": "relationship--44c91929-3473-443c-91be-5afa81582dfa", "modified": "2026-04-29T14:23:06.019Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--10ffac09-e42d-4f56-ab20-db94c67d76ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6305', 0, 65, '09-mitre-attack', 'retrieved', '7B0962155F45B245F743B7C01D755CDFAAA9E9FDB1612421FE8FAD07E6711354', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
