VALUES ('doc-09-mitre-attack-p0-6307', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-12T14:18:38.929Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In some cases a local DNS sinkhole may be used to help prevent behaviors associated with dynamic resolution.", "id": "relationship--5632a2de-e231-4ef0-971b-6cdb2750d410", "modified": "2026-04-29T14:23:06.043Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--7bd9c723-2f78-4309-82c5-47cad406572b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6307', 0, 47, '09-mitre-attack', 'retrieved', 'BA4FAC69F141F68C58732BBCDDDD0239BC9FE2BCC5776548857BAB99E871F444', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
