VALUES ('doc-09-mitre-attack-p0-6308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-14T22:24:22.080Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Web proxies can be used to enforce external network communication policy that prevents use of unauthorized external services.", "id": "relationship--5e165901-44c0-423e-972b-d626b0c7cebf", "modified": "2026-04-29T14:23:06.053Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--f7827069-0bf2-4764-af4f-23fae0d181b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6308', 0, 47, '09-mitre-attack', 'retrieved', '3E4F35049844C633C7FCF3DEE9732C31AD9D9391D7BA7DCCE2C0EE196F279935', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
