VALUES ('doc-09-mitre-attack-p0-6309', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:28:45.461Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If a link is being visited by a user, block unknown or unused files in transit by default that should not be downloaded or by policy from suspicious sites as a best practice to prevent some vectors, such as .scr, .exe, .pif, .cpl, etc. Some download scanning devices can open and analyze compressed and encrypted formats, such as zip and rar that may be used to conceal malicious files.", "id": "relationship--66551074-a1e3-439c-a996-c1f7ca8136e2", "modified": "2026-04-29T14:23:06.064Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--8c32eb4d-805f-4fc5-bf60-c4d476c131b5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6309', 0, 98, '09-mitre-attack', 'retrieved', '5E3AEB09347850BEB78AA9F6E4F58401CE5989B004AFDB464D15A7128D95C820', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
