INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6311', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T13:38:13.109Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adblockers can help prevent malicious code served through ads from executing in the first place. Script blocking extensions can also help to prevent the execution of JavaScript. \n\nConsider disabling browser push notifications from certain applications and browsers.(Citation: mac security virus popup)(Citation: push notifications -infosecinstitute)(Citation: site notifications - krebsonsecurity)", "external_references": [{"description": "Dan Virgillito. (2022, January 27). Malicious push notifications: Is that a real or fake Windows Defender update?. Retrieved March 14, 2025.", "source_name": "push notifications -infosecinstitute", "url": "https://www.infosecinstitute.com/resources/security-awareness/malicious-push-notifications-is-that-a-real-or-fake-windows-defender-update/"}, {"description": "David Balaban. (2022, October 7). Remove Guroshied virus popup from Mac. Retrieved March 14, 2025.", "source_name": "mac security virus popup", "url": "https://macsecurity.net/view/543-remove-guroshied-mac"}, {"description": "Frank Angiolelli, Indelible LLC, Malwarebytes, McAfee, Norton, Pieter Arntz, PushWelcome. (2020, November 17). Be Very Sparing in Allowing Site Notifications. Retrieved March 14, 2025.", "source_name": "site notifications - krebsonsecurity", "url": "https://krebsonsecurity.com/2020/11/be-very-sparing-in-allowing-site-notifications/"}], "id": "relationship--7d8a729c-3656-4b31-85c0-42b75001f913", "modified": "2026-04-29T14:23:06.097Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--d742a578-d70e-4d0e-96a6-02a9c30204e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6311', 0, 161, '09-mitre-attack', 'retrieved', 'F4B1CC4BF868E0AF18043F4E408D90D805F8194DFF23EA5A69A18B0903F706B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
