VALUES ('doc-09-mitre-attack-p0-6312', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-02T19:28:55.581Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Determine if certain social media sites, personal webmail services, or other service that can be used for spearphishing is necessary for business operations and consider blocking access if activity cannot be monitored well or if it poses a significant risk.", "id": "relationship--7f18d24e-fffe-413f-96ff-612b3e9bedd6", "modified": "2026-04-29T14:23:06.099Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--f6ad61ee-65f3-4bd0-a3f5-2f0accb36317", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6312', 0, 69, '09-mitre-attack', 'retrieved', '9C8511E1F3E55940B7999F0A5A0C356576466F741CE284B31B12C8FF76FB8A22', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
