VALUES ('doc-09-mitre-attack-p0-6314', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-10T17:45:00.272Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In some cases a local DNS sinkhole may be used to help prevent DGA-based command and control at a reduced cost.", "id": "relationship--909147b8-d0f8-4222-b62c-10f1d8bec2ec", "modified": "2026-04-29T14:23:06.122Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--118f61a5-eb3e-4fb6-931f-2096647f4ecd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6314', 0, 50, '09-mitre-attack', 'retrieved', '3A64CA16CE33223CD823A58E7E42822950D51816679074FA6E3C8FF3EA343AD9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
