VALUES ('doc-09-mitre-attack-p0-6317', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-02T18:49:28.119Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Determine if certain websites or attachment types (ex: .scr, .exe, .pif, .cpl, etc.) that can be used for phishing are necessary for business operations and consider blocking access if activity cannot be monitored well or if it poses a significant risk.", "id": "relationship--a205b0ce-df00-40ae-b626-7dc3e8146d45", "modified": "2026-04-29T14:23:06.145Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--a62a8db3-f23a-4d8f-afd6-9dbc77e7813b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6317', 0, 70, '09-mitre-attack', 'retrieved', '83562D0B0A88525E5CCC9B398200912C684D472D6C67F7F5E03D2449E72C050B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
