VALUES ('doc-09-mitre-attack-p0-6318', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-18T12:58:32.533Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If a link is being requested by a user, block unknown or unused files in transit by default that should not be downloaded or by policy from suspicious sites as a best practice to prevent some vectors, such as `.scr`, `.exe`, `.pif`, `.cpl`, etc. ", "id": "relationship--a46e37b7-adfe-410c-a820-9d4c4037734d", "modified": "2026-04-29T14:23:06.149Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--e261a979-f354-41a8-963e-6cadac27c4bf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6318', 0, 74, '09-mitre-attack', 'retrieved', '482E28DFB385A8866C37C42736C1BA6F0FDB34D0CB192A4A8B2F06E6580D8817', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
