VALUES ('doc-09-mitre-attack-p0-6330', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-02T19:05:18.264Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Block unknown or unused attachments by default that should not be transmitted over email as a best practice to prevent some vectors, such as .scr, .exe, .pif, .cpl, etc. Some email scanning devices can open and analyze compressed and encrypted formats, such as zip and rar that may be used to conceal malicious attachments.", "id": "relationship--f2f68eb7-4110-4750-9d1c-58774036672b", "modified": "2026-04-29T14:23:06.255Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--21da4fd4-27ad-4e9c-b93d-0b9b14d02c96", "spec_version": "2.1", "target_ref": "attack-pattern--2e34237d-8574-43f6-aace-ae2915de8597", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6330', 0, 83, '09-mitre-attack', 'retrieved', '351BF51777ED31BA6BE30CF621CD7FFA81351D7BFC16756E6CE10CC85B3E65E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
