VALUES ('doc-09-mitre-attack-p0-6331', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-13T16:53:10.338Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Only install browser extensions from trusted sources that can be verified. Browser extensions for some browsers can be controlled through Group Policy. Change settings to prevent the browser from installing extensions without sufficient permissions.", "id": "relationship--08dea09a-e7f5-4e6d-a142-73548f6f1498", "modified": "2026-04-29T14:23:05.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--23843cff-f7b9-4659-a7b7-713ef347f547", "spec_version": "2.1", "target_ref": "attack-pattern--278716b1-61ce-4a74-8d17-891d0c494101", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6331', 0, 63, '09-mitre-attack', 'retrieved', 'C17F0015FF2BF3045FAEC96DF7773158023DC43DA8613C9542C3EA6BFDEE1476', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
