VALUES ('doc-09-mitre-attack-p0-6332', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-05-22T19:50:52.628Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Where possible, consider requiring developers to pull from internal repositories containing verified and approved packages rather than from external ones. ", "id": "relationship--2141b8f5-4a86-46b2-9fe6-0f24f629bdcf", "modified": "2026-04-29T14:23:05.950Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--23843cff-f7b9-4659-a7b7-713ef347f547", "spec_version": "2.1", "target_ref": "attack-pattern--73b24a10-6bf4-4af1-a81e-67b8bcb6c4e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6332', 0, 50, '09-mitre-attack', 'retrieved', '8E7E20D53FB439EF621EF573B70A6C6A467946C729A5A1B96E4D9FE21B976B16', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
