VALUES ('doc-09-mitre-attack-p0-6349', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-11T16:20:44.146Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure applications are using Apple''s developer guidance which enables hardened runtime.(Citation: Apple Developer Doco Hardened Runtime)", "external_references": [{"description": "Apple Inc.. (2021, January 1). Hardened Runtime: Manage security protections and resource access for your macOS apps.. Retrieved March 24, 2021.", "source_name": "Apple Developer Doco Hardened Runtime", "url": "https://developer.apple.com/documentation/security/hardened_runtime"}], "id": "relationship--3c5b3ca4-af5a-47dd-8dd4-57d2a690c2a9", "modified": "2026-04-29T14:23:06.006Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--7d20fff9-8751-404e-badd-ccd71bda0236", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6349', 0, 76, '09-mitre-attack', 'retrieved', '9E776CD79BBCA88D3058BC8C0A8A6E78304E40946EEE41B4B4EB0D54B33CB66D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
