VALUES ('doc-09-mitre-attack-p0-6350', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-24T19:44:22.503Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application developers should be cautious when selecting third-party libraries to integrate into their application. Additionally, where possible, developers should lock software dependencies to specific versions rather than pulling the latest version on build.(Citation: Cider Security Top 10 CICD Security Risks)", "external_references": [{"description": "Daniel Krivelevich and Omer Gil. (n.d.). Top 10 CI/CD Security Risks. Retrieved November 17, 2024.", "source_name": "Cider Security Top 10 CICD Security Risks", "url": "https://web.archive.org/web/20220316130828/https://www.cidersecurity.io/top-10-cicd-security-risks/"}], "id": "relationship--3c740c2b-293a-4f6b-98a8-dde4a215eea1", "modified": "2026-04-29T14:23:06.006Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--3f18edba-28f4-4bb9-82c3-8aa60dcac5f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6350', 0, 96, '09-mitre-attack', 'retrieved', '2C59C77E1885423A314D885804C497E34850DFBF1B007309AAF387FDCC146A61', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
