VALUES ('doc-09-mitre-attack-p0-6351', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-01T02:31:47.468Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When possible, include hash values in manifest files to help prevent side-loading of malicious libraries.(Citation: FireEye DLL Side-Loading)", "external_references": [{"description": "Amanda Steward. (2014). FireEye DLL Side-Loading: A Thorn in the Side of the Anti-Virus Industry. Retrieved March 13, 2020.", "source_name": "FireEye DLL Side-Loading", "url": "https://www.fireeye.com/content/dam/fireeye-www/global/en/current-threats/pdfs/rpt-dll-sideloading.pdf"}], "id": "relationship--4f806196-7c20-4923-ae01-8f0f7f27a4a7", "modified": "2026-04-29T14:23:06.033Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--aedfca76-3b30-4866-b2aa-0f1d7fd1e4b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6351', 0, 74, '09-mitre-attack', 'retrieved', '0859DD61160B70B6D01781C0D83D1536A85E2D6046841DBF69DAE3C307EF4477', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
