VALUES ('doc-09-mitre-attack-p0-6353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T20:18:18.906Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application developers should consider taking measures to validate authentication requests by enabling one-time passwords, providing timestamps or sequence numbers for messages sent, using digital signatures, and/or using random session keys.(Citation: Comparitech Replay Attack)(Citation: Bugcrowd Replay Attack)", "external_references": [{"description": "Bugcrowd. (n.d.). Replay Attack. Retrieved September 27, 2023.", "source_name": "Bugcrowd Replay Attack", "url": "https://www.bugcrowd.com/glossary/replay-attack/"}, {"description": "Justin Schamotta. (2022, October 28). What is a replay attack?. Retrieved September 27, 2023.", "source_name": "Comparitech Replay Attack", "url": "https://www.comparitech.com/blog/information-security/what-is-a-replay-attack/"}], "id": "relationship--6de628ac-2f5b-4563-8f54-c5243109221e", "modified": "2026-04-29T14:23:06.075Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--9c306d8d-cde7-4b4c-b6e8-d0bb16caca36", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6353', 0, 102, '09-mitre-attack', 'retrieved', '426A7D78B80FBEE3EC04112E53712338058B369F06B49DA600226695C23032DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
