VALUES ('doc-09-mitre-attack-p0-6354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-29T17:43:23.251Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application developers should consider limiting the requirements for custom or otherwise difficult to manage file/folder exclusions. Where possible, install applications to trusted system folder paths that are already protected by restricted file and directory permissions.", "id": "relationship--7acdcde3-1065-4393-ae6b-80ac95b2607d", "modified": "2026-04-29T14:23:06.093Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--09b008a9-b4eb-462a-a751-a0eb58050cd9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6354', 0, 64, '09-mitre-attack', 'retrieved', 'C1A12AB5BC68E9883838F94BE751A734A72C54B069BC491E4319CD12B78ABABB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
