VALUES ('doc-09-mitre-attack-p0-6355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T15:03:14.582Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider implementing token binding strategies, such as Azure AD token protection or OAuth Proof of Possession, that cryptographically bind a token to a secret. This may prevent the token from being used without knowledge of the secret or possession of the device the token is tied to.(Citation: Microsoft Token Protection 2023)(Citation: Okta DPoP 2023)", "external_references": [{"description": "Microsoft. (2023, October 23). Conditional Access: Token protection (preview). Retrieved January 2, 2024.", "source_name": "Microsoft Token Protection 2023", "url": "https://learn.microsoft.com/en-us/entra/identity/conditional-access/concept-token-protection"}, {"description": "Venkat Viswanathan. (2023, June 13). A leap forward in token security: Okta adds support for DPoP. Retrieved January 2, 2024.", "source_name": "Okta DPoP 2023", "url": "https://www.okta.com/blog/2023/06/a-leap-forward-in-token-security-okta-adds-support-for-dpop/"}], "id": "relationship--9c41ad44-8a0f-40bc-b832-ad7aa99e5290", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--f005e783-57d4-4837-88ad-dbe7faee1c51", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6355', 0, 132, '09-mitre-attack', 'retrieved', '388C9527758BB4E9C29D4291BFFA01D1998013541419CE2CFB8BCD8D8DD6EDC7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
