VALUES ('doc-09-mitre-attack-p0-6356', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-12T06:45:36.902Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enable the Hardened Runtime capability when developing applications. Do not include the com.apple.security.get-task-allow entitlement with the value set to any variation of true. ", "id": "relationship--9e753c36-66d8-4f48-8b06-fbb9fdc92f76", "modified": "2026-04-29T14:23:06.141Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--8252f135-ed26-4ce1-ae61-f26e94429a19", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6356', 0, 53, '09-mitre-attack', 'retrieved', 'E43817E799931C87BB6507E9FB7615A3805B6ED6486ACD26E93991C0292F8D78', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
