VALUES ('doc-09-mitre-attack-p0-6358', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-09T13:02:09.414Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application developers uploading to public code repositories should be careful to avoid publishing sensitive information such as credentials and API keys.", "id": "relationship--aae309ee-9d15-4188-8f74-68c581a3a720", "modified": "2026-04-29T14:23:06.157Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--70910fbd-58dc-4c1c-8c48-814d11fcd022", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6358', 0, 50, '09-mitre-attack', 'retrieved', 'C26CC81E6999195B5EB193EB123BAD235AD7BC40655A2DC7585C7C74F5FEED29', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
