VALUES ('doc-09-mitre-attack-p0-6359', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-10T18:46:45.553Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that applications do not store sensitive data or credentials insecurely. (e.g. plaintext credentials in code, published credentials in repositories, or credentials in public cloud storage).", "id": "relationship--c8acdf40-8237-487f-8255-91afa327705d", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6359', 0, 55, '09-mitre-attack', 'retrieved', '5215058517967E5DA2FEE86EAFBC11FB303D74A747880C6A1FF5838CE016F86C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
