VALUES ('doc-09-mitre-attack-p0-6360', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-13T06:37:46.726Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure applications to use the application bundle structure which leverages the /Resources folder location.(Citation: Apple App Security Overview) ", "external_references": [{"description": "Apple Inc. (2021, February 18). App security overview. Retrieved October 12, 2021.", "source_name": "Apple App Security Overview", "url": "https://support.apple.com/guide/security/app-security-overview-sec35dd877d0/1/web/1"}], "id": "relationship--da7b2203-dade-4ec0-85a5-dada9409ae2f", "modified": "2026-04-29T14:23:06.223Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--b22e5153-ac28-4cc6-865c-2054e36285cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6360', 0, 69, '09-mitre-attack', 'retrieved', '354CDDEA257FA0C201CE33ABFBC1D7B74EAC55200B7CB19BF984EA1DD6AD6CAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
