VALUES ('doc-09-mitre-attack-p0-6361', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-30T20:51:12.944Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When possible, include hash values in manifest files to help prevent side-loading of malicious libraries. ", "id": "relationship--e575c5f9-c9ff-4b84-920a-c483d9442c3a", "modified": "2026-04-29T14:23:06.237Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6361', 0, 45, '09-mitre-attack', 'retrieved', 'BCAC03E9C4EF3772F4AE6D9DD7F14258A3D88D21EE326494D371493E8F238DA5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
