VALUES ('doc-09-mitre-attack-p0-6362', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-24T19:43:18.719Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application developers should be cautious when selecting third-party libraries to integrate into their application. Additionally, where possible, developers should lock software dependencies to specific versions rather than pulling the latest version on build.(Citation: Cider Security Top 10 CICD Security Risks) GitHub Actions may be pinned to a specific commit hash rather than a tag or branch.(Citation: Unit 42 Palo Alto GitHub Actions Supply Chain Attack 2025) ", "external_references": [{"description": "Daniel Krivelevich and Omer Gil. (n.d.). Top 10 CI/CD Security Risks. Retrieved November 17, 2024.", "source_name": "Cider Security Top 10 CICD Security Risks", "url": "https://web.archive.org/web/20220316130828/https://www.cidersecurity.io/top-10-cicd-security-risks/"}, {"description": "Omer Gilm Aviad Hahami, Asi Greenholts, and Yaron Avital. (2025, March 20). GitHub Actions Supply Chain Attack: A Targeted Attack on Coinbase Expanded to the Widespread tj-actions/changed-files Incident: Threat Assessment . Retrieved May 22, 2025.", "source_name": "Unit 42 Palo Alto GitHub Actions Supply Chain Attack 2025", "url": "https://unit42.paloaltonetworks.com/github-actions-supply-chain-attack"}], "id": "relationship--ef48b966-327f-4795-a1d0-4baf949fad2f", "modified": "2026-04-29T14:23:06.251Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--25dc1ce8-eb55-4333-ae30-a7cb4f5894a1", "spec_version": "2.1", "target_ref": "attack-pattern--191cc6af-1bb2-4344-ab5f-28e496638720", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-0