VALUES ('doc-09-mitre-attack-p0-6382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-10T18:03:40.595Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications may send push notifications to verify a login as a form of multi-factor authentication (MFA). Train users to only accept valid push notifications and to report suspicious push notifications.", "id": "relationship--4d0c0d1b-94a7-4518-b57e-e79212354bbf", "modified": "2026-04-29T14:23:06.030Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--c3d4bdd9-2cfe-4a80-9d0c-07a29ecdce8f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6382', 0, 59, '09-mitre-attack', 'retrieved', '7CA6707682BC45DD2B789F1FD32242A5DB563725BAE6A83C871F1A352A3EB040', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
