VALUES ('doc-09-mitre-attack-p0-6383', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-15T12:05:58.908Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to be suspicious about certificate errors. Adversaries may use their own certificates in an attempt to intercept HTTPS traffic. Certificate errors may arise when the application’s certificate does not match the one expected by the host.", "id": "relationship--59c65423-347b-4a09-a24d-c228faaa5119", "modified": "2026-04-29T14:23:06.047Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--cabe189c-a0e3-4965-a473-dcff00f17213", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6383', 0, 67, '09-mitre-attack', 'retrieved', '7583446CCFBC572C625A57A8E4D13B9AE0E12097E3AF7551BBF6C8FBC740AE93', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
