VALUES ('doc-09-mitre-attack-p0-6384', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T04:17:45.388Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Users can be trained to identify social engineering techniques and spearphishing attempts. Additionally, users may perform visual checks of the domains they visit; however, homographs in ASCII and in IDN domains and URL schema obfuscation may render manual checks difficult. Phishing training and other cybersecurity training may raise awareness to check URLs before visiting the sites.", "id": "relationship--59f80c0d-e8d7-48f6-960a-3d4b593f8b33", "modified": "2026-04-29T14:23:06.048Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--2d3f5b3c-54ca-4f4d-bb1f-849346d31230", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6384', 0, 85, '09-mitre-attack', 'retrieved', '07F9C22A0E02987BD1B92609468AA4BC2C036BA730CC2BBB45E00363B42957D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
