VALUES ('doc-09-mitre-attack-p0-6388', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-08T19:29:17.546Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to be aware of impersonation tricks and how to counter them, for example confirming incoming requests through an independent platform like a phone call or in-person, to reduce risk.", "id": "relationship--74a8ec0f-20d4-4175-bfc3-517d57956eff", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--cd92d2b8-ce43-4666-9472-f1b4b9f4f8be", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6388', 0, 60, '09-mitre-attack', 'retrieved', 'F8349FEFB91803BB71A6840128C693CCD69AAFCBC3322FFEBADC0C5D802C97E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
