VALUES ('doc-09-mitre-attack-p0-6396', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-18T20:51:06.322Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train and encourage users to identify social engineering techniques used to enable financial theft. Also consider training users on procedures to prevent and respond to swatting and doxing, acts increasingly deployed by financially motivated groups to further coerce victims into satisfying ransom/extortion demands.(Citation: Cyber Safety Review Board: Lapsus)(Citation: SWAT-hospital)", "external_references": [{"description": "CISA. (2023, August). Cyber Safety Review Board: Lapsus. Retrieved January 5, 2024.", "source_name": "Cyber Safety Review Board: Lapsus", "url": "https://www.cisa.gov/sites/default/files/2023-08/CSRB_Lapsus%24_508c.pdf"}, {"description": "Giles, Bruce. (2024, January 4). Hackers threaten to send SWAT teams to Fred Hutch patients'' homes. Retrieved January 5, 2024.", "source_name": "SWAT-hospital", "url": "https://www.beckershospitalreview.com/cybersecurity/hackers-threaten-to-send-swat-teams-to-fred-hutch-patients-homes.html"}], "id": "relationship--90922ab5-2463-4e3a-a23e-13958cce9795", "modified": "2026-04-29T14:23:06.122Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--851e071f-208d-4c79-adc6-5974c85c78f3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6396', 0, 125, '09-mitre-attack', 'retrieved', '4A9EE3EFCF819F66E614DCC9F64C0A8C0D5D4DA8243D038E149FDEC6A4648633', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type"