VALUES ('doc-09-mitre-attack-p0-6401', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-05-22T19:51:05.321Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train developers to be aware of the existence of malicious libraries and how to avoid installing them. ", "id": "relationship--97d77f42-8b8e-48e1-b772-b6cb5c435249", "modified": "2026-04-29T14:23:06.132Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--73b24a10-6bf4-4af1-a81e-67b8bcb6c4e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6401', 0, 47, '09-mitre-attack', 'retrieved', 'BB7CACDF58526F5C2127040E6C6287786E155ADAAC96F908482D696D3502CAA4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
