VALUES ('doc-09-mitre-attack-p0-6404', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T04:16:36.949Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Users can be trained to identify social engineering techniques and spearphishing attempts.", "id": "relationship--a581fb2c-604a-4417-b782-cafd76b11c37", "modified": "2026-04-29T14:23:06.150Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--8982a661-d84c-48c0-b4ec-1db29c6cf3bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6404', 0, 41, '09-mitre-attack', 'retrieved', 'A70F78A69760653B24143113129FE26411E9A43DC2D5BB72A0F7647593A36001', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
