VALUES ('doc-09-mitre-attack-p0-6408', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T18:39:33.161Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit credential overlap across accounts and systems by training users and administrators not to use the same password for multiple accounts.", "id": "relationship--b6583fd8-89f7-4494-8690-3456391bf193", "modified": "2026-04-29T14:23:06.174Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--65f2d882-3f41-4d48-8a06-29af77ec9f90", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6408', 0, 50, '09-mitre-attack', 'retrieved', '49A62A93B7EF296BEABD593D84079B6A9F4179F26A49E340730B01957BA32CD7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
