VALUES ('doc-09-mitre-attack-p0-6409', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-18T15:54:51.207Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use user training as a way to bring awareness and raise suspicion for potentially malicious events and dialog boxes (ex: Office documents prompting for credentials).", "id": "relationship--b921aed3-07ce-49b0-8051-48807fa82ea7", "modified": "2026-04-29T14:23:06.178Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--a2029942-0a85-4947-b23c-ca434698171d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6409', 0, 54, '09-mitre-attack', 'retrieved', '7A7AAC1524FE78FA923104A1C8896D16FDCC07C87D3E5E94CE41B5602A4C2C24', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
