VALUES ('doc-09-mitre-attack-p0-6411', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-17T14:40:58.242Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to be suspicious about access points marked as “Open” or “Unsecure” as well as certificate errors. Certificate errors may arise when the application’s certificate does not match the one expected by the host.", "id": "relationship--bb6edf0f-f2c3-4f6d-b545-f79a57423cd2", "modified": "2026-04-29T14:23:06.181Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--48b836c6-e4ca-435a-82a3-29c03e5b492e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6411', 0, 64, '09-mitre-attack', 'retrieved', 'A4D4CAE7D13B416E15A6021142953D15B5726B2020BB9674B57B3A262CFF0250', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
