VALUES ('doc-09-mitre-attack-p0-6414', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T15:13:51.145Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful spearphishing, social engineering, and other techniques that involve user interaction.", "id": "relationship--c041783a-0746-49fd-aa9c-3c680029b3a5", "modified": "2026-04-29T14:23:06.188Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--d742a578-d70e-4d0e-96a6-02a9c30204e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6414', 0, 58, '09-mitre-attack', 'retrieved', 'A2FA8FAC68A8EBE5C90520C71AB8C2B7D80C577879967DF841E7A07E194A66D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
