VALUES ('doc-09-mitre-attack-p0-6418', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-15T15:40:45.933Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Reduces success of phishing/vishing/impersonation and modern “human interface” lures.(Citation: SE SentinelOne 2)(Citation: Sophos User Interaction)(Citation: Unit 42 Global Incident Response Report 2026)", "external_references": [{"description": "Jagadeesh Chandraiah, Tonmoy Jitu, Dmitry Samosseiko, Matt Wixey. (2026, March 11). Evil evolution: ClickFix and macOS infostealers. Retrieved April 15, 2026.", "source_name": "Sophos User Interaction", "url": "https://www.sophos.com/en-us/blog/evil-evolution-clickfix-and-macos-infostealers"}, {"description": "Palo Alto Networks Unit 42. (n.d.). Global Incident Response Report 2026. Retrieved April 15, 2026.", "source_name": "Unit 42 Global Incident Response Report 2026", "url": "https://www.paloaltonetworks.com/resources/research/unit-42-incident-response-report#:~:text=The%20Browser%20Attack%20Surface:%20Attacks%20at%20the%20Human%20Interface&text=The%20site%20used%20social-engineering,deployment%20and%20broader%20operational%20disruption"}, {"description": "SentinelOne. (2025, August 19). 15 Types of Social Engineering Attacks. Retrieved April 15, 2026.", "source_name": "SE SentinelOne 2", "url": "https://www.sentinelone.com/cybersecurity-101/threat-intelligence/types-of-social-engineering-attacks/"}], "id": "relationship--d9f8babb-0b1b-4eb9-aa0c-13c5507561ce", "modified": "2026-04-29T14:23:06.223Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--41e4d77a-6275-4976-9e35-785985598519", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "