VALUES ('doc-09-mitre-attack-p0-6425', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-02T18:49:28.130Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Users can be trained to identify social engineering techniques and phishing emails.", "id": "relationship--ee935350-f68f-4bd7-bfca-878ae48a2b97", "modified": "2026-04-29T14:23:06.250Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--a62a8db3-f23a-4d8f-afd6-9dbc77e7813b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6425', 0, 41, '09-mitre-attack', 'retrieved', '24FE7695DBB40CCD8ED7B0BD75B848B7C1927F3A3FB311668664F29A14CBCC4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
