VALUES ('doc-09-mitre-attack-p0-6426', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-31T15:01:12.717Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful social engineering via e-mail bombing.", "id": "relationship--f494bf94-fe0e-4590-8991-470da4bcb4e0", "modified": "2026-04-29T14:23:06.257Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--bed81616-3dde-4685-be6e-ba9820f9a7ed", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6426', 0, 53, '09-mitre-attack', 'retrieved', '139C12B12325D50BDC4A17E968A69452A1F52755907DF5675FCD75A220E95CE8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
