VALUES ('doc-09-mitre-attack-p0-6428', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T18:15:06.946Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Holding the Shift key while logging in prevents apps from opening automatically.(Citation: Re-Open windows on Mac)", "external_references": [{"description": "Apple. (2016, December 6). Automatically re-open windows, apps, and documents on your Mac. Retrieved July 11, 2017.", "source_name": "Re-Open windows on Mac", "url": "https://support.apple.com/en-us/HT204005"}], "id": "relationship--f5499769-be56-4995-b993-0a2bc59a0f08", "modified": "2026-04-29T14:23:06.258Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--e5cc9e7a-e61a-46a1-b869-55fb6eab058e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6428', 0, 71, '09-mitre-attack', 'retrieved', '5082F822E0AF29F37D3B0DE23CAB944234FAACCADF4F183620C233D75BC338CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
