VALUES ('doc-09-mitre-attack-p0-6429', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-14T16:25:38.695Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to identify aspects of phishing attempts where they''re asked to enter credentials into a site that has the incorrect domain for the application they are logging into. Additionally, train users not to run untrusted JavaScript in their browser, such as by copying and pasting code or dragging and dropping bookmarklets.", "id": "relationship--f780f9d8-1baa-41b7-b7a1-acba717df0ab", "modified": "2026-04-29T14:23:06.261Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--10ffac09-e42d-4f56-ab20-db94c67d76ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6429', 0, 81, '09-mitre-attack', 'retrieved', '557B37110AE570846A3454614B997CF57743465D3E1BF1EE4745AA14BBEE761E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
