VALUES ('doc-09-mitre-attack-p0-6430', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-01T02:15:49.913Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Train users to only accept 2FA/MFA requests from login attempts they initiated, to review source location of the login attempt prompting the 2FA/MFA requests, and to report suspicious/unsolicited prompts.", "id": "relationship--f78baa1d-e84a-4f32-a1a4-67972bdd94ea", "modified": "2026-04-29T14:23:06.261Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2a4f6c11-a4a7-4cb9-b0ef-6ae1bb3a718a", "spec_version": "2.1", "target_ref": "attack-pattern--954a1639-f2d6-407d-aef3-4917622ca493", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6430', 0, 58, '09-mitre-attack', 'retrieved', '7DE4FFA3384ACAB809A353E02A41E5A1FB6EEC30846AB389A5EEC8C8C2A16DBF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
