INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6431', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-26T19:30:46.421Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Turn off UAC''s privilege elevation for standard users [HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System] to automatically deny elevation requests, add: \"ConsentPromptBehaviorUser\"=dword:00000000 . Consider enabling installer detection for all users by adding: \"EnableInstallerDetection\"=dword:00000001 . This will prompt for a password for installation and also log the attempt. To disable installer detection, instead add: \"EnableInstallerDetection\"=dword:00000000 . This may prevent potential elevation of privileges through exploitation during the process of UAC detecting the installer, but will allow the installation process to continue without being logged. (Citation: Executable Installers are Vulnerable)", "external_references": [{"description": "Stefan Kanthak. (2015, December 8). Executable installers are vulnerable^WEVIL (case 7): 7z*.exe allows remote code execution with escalation of privilege. Retrieved December 4, 2014.", "source_name": "Executable Installers are Vulnerable", "url": "https://seclists.org/fulldisclosure/2015/Dec/34"}], "id": "relationship--214e4329-960c-4c25-8620-b9573a6e06dc", "modified": "2026-04-29T14:23:05.950Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2c2ad92a-d710-41ab-a996-1db143bb4808", "spec_version": "2.1", "target_ref": "attack-pattern--aedfca76-3b30-4866-b2aa-0f1d7fd1e4b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6431', 0, 144, '09-mitre-attack', 'retrieved', '801771454CBB4D802C3576C1A6DB6046998B8FCAD7A3B0264D7D7767B40C05BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6432', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T16:36:51.574Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enable pass the hash mitigations to apply UAC restrictions to local accounts on network logon. The associated Registry key is located HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\LocalAccountTokenFilterPolicy .\n\nThrough GPO: Computer Configuration > [Policies] > Administrative Templates > SCM: Pass the Hash Mitigations: Apply UAC restrictions to local accounts on network logons.(Citation: GitHub IAD Secure Host Baseline UAC Filtering)", "external_references": [{"description": "NSA IAD. (2017, January 24). MS Security Guide. Retrieved December 18, 2017.", "source_name": "GitHub IAD Secure Host Baseline UAC Filtering", "url": "https://github.com/iadgov/Secure-Host-Baseline/blob/master/Windows/Group%20Policy%20Templates/en-US/SecGuide.adml"}], "id": "relationship--2dcd6644-f1d4-4001-81a5-95701fd29360", "modified": "2026-04-29T14:23:05.967Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2c2ad92a-d710-41ab-a996-1db143bb4808", "spec_version": "2.1", "target_ref": "attack-pattern--e624264c-033a-424d-9fd7-fc9c3bbdb03e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6432', 0, 106, '09-mitre-attack', 'retrieved', '6C88CB43D190908A0E0601760C18B98D98B92C8CDEAE17BCEB1C692E98AE0DCF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
