VALUES ('doc-09-mitre-attack-p0-6433', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T14:56:24.415Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Changing UAC settings to \"Always Notify\" will give the user more visibility when UAC elevation is requested, however, this option will not be popular among users due to the constant UAC interruptions.", "id": "relationship--5329d477-4378-4635-8da8-ed427d7863fc", "modified": "2026-04-29T14:23:06.039Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2c2ad92a-d710-41ab-a996-1db143bb4808", "spec_version": "2.1", "target_ref": "attack-pattern--42fe883a-21ea-4cfb-b94a-78b6476dcc83", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6433', 0, 61, '09-mitre-attack', 'retrieved', '245B6593D66DAB353ED8935F3283DB3DB05E4E12D0586131EB2347A68AE79722', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
