VALUES ('doc-09-mitre-attack-p0-6434', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T11:12:18.716Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Turn off UAC''s privilege elevation for standard users [HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System] to automatically deny elevation requests, add: \"ConsentPromptBehaviorUser\"=dword:00000000 . Consider enabling installer detection for all users by adding: \"EnableInstallerDetection\"=dword:00000001 . This will prompt for a password for installation and also log the attempt. To disable installer detection, instead add: \"EnableInstallerDetection\"=dword:00000000 . This may prevent potential elevation of privileges through exploitation during the process of UAC detecting the installer, but will allow the installation process to continue without being logged. (Citation: Executable Installers are Vulnerable)", "external_references": [{"description": "Stefan Kanthak. (2015, December 8). Executable installers are vulnerable^WEVIL (case 7): 7z*.exe allows remote code execution with escalation of privilege. Retrieved December 4, 2014.", "source_name": "Executable Installers are Vulnerable", "url": "https://seclists.org/fulldisclosure/2015/Dec/34"}], "id": "relationship--681ea412-54a2-4580-960f-98e1219fff1f", "modified": "2026-04-29T14:23:06.067Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2c2ad92a-d710-41ab-a996-1db143bb4808", "spec_version": "2.1", "target_ref": "attack-pattern--70d81154-b187-45f9-8ec5-295d01255979", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6434', 0, 144, '09-mitre-attack', 'retrieved', '0A6C551F33F42515064FC443D746C700388577D2F6AE